window.FAQ=(window.FAQ||[]).concat([
 {id:'fex-001',thema:'fiscaal-eigen-woning',vraag:'Wanneer is een woning fiscaal een eigen woning?',antwoord:`Een woning is fiscaal een eigen woning als die de klant of zijn fiscale partner toebehoort en hem duurzaam als hoofdverblijf ter beschikking staat. Het gaat om de feitelijke situatie, niet alleen om de inschrijving. Is aan deze voorwaarden niet voldaan, dan valt de woning in box 3.`,tags:['eigen woning','hoofdverblijf','definitie'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-002',thema:'fiscaal-eigen-woning',vraag:'Is inschrijving in de BRP doorslaggevend voor het hoofdverblijf?',antwoord:`Nee. De inschrijving in de Basisregistratie Personen is een belangrijke aanwijzing, maar niet doorslaggevend. De Belastingdienst kijkt naar alle feiten, zoals waar de klant feitelijk woont, slaapt en zijn sociale leven heeft. Leg bij twijfel vast waarom de woning het hoofdverblijf is.`,tags:['hoofdverblijf','brp','bewijs'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-003',thema:'fiscaal-eigen-woning',vraag:'Kan een woonboot een eigen woning zijn?',antwoord:`Ja. Een woonboot die duurzaam als hoofdverblijf dient, wordt voor de eigenwoningregeling gelijkgesteld met een woning. Hetzelfde geldt voor een woonwagen. De gewone voorwaarden voor eigenwoningschuld en aflossingseis blijven gelden. Controleer wel of de geldverstrekker de woonboot als onderpand accepteert.`,tags:['woonboot','woonwagen','eigen woning'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-004',thema:'fiscaal-eigen-woning',vraag:'Hoort een garage of berging bij de eigen woning?',antwoord:`Een garage, berging of tuin die bij de woning hoort, valt als aanhorigheid onder de eigen woning. Een lening voor de aankoop van zo een aanhorigheid kan daardoor eigenwoningschuld zijn. Een losse garage op afstand die niet bij de woning hoort, valt doorgaans in box 3. Leg de situatie vast in het dossier.`,tags:['aanhorigheid','garage','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-005',thema:'fiscaal-eigen-woning',vraag:'Blijft de woning een eigen woning bij tijdelijke afwezigheid?',antwoord:`Ja, onder voorwaarden. Een woning kan eigen woning blijven als de klant tijdelijk elders verblijft, bijvoorbeeld bij uitzending naar het buitenland. De woning mag in die periode niet aan derden ter beschikking worden gesteld. Wordt de woning verhuurd, dan vervalt de eigenwoningstatus voor die periode.`,tags:['tijdelijke afwezigheid','uitzending','verhuur'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-006',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er fiscaal als een klant tijdelijk naar het buitenland vertrekt en de woning verhuurt?',antwoord:`Tijdens de verhuur is de woning geen eigen woning. De woning en de schuld vallen dan in box 3 en de rente is niet aftrekbaar. Dat kan ook gevolgen hebben voor overgangsrecht en eigenwoningreserve. Laat de gevolgen vooraf fiscaal toetsen en controleer of de geldverstrekker toestemming geeft voor verhuur.`,tags:['uitzending','verhuur','box 3'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-007',thema:'fiscaal-eigen-woning',vraag:'Kan een woning in aanbouw al een eigen woning zijn?',antwoord:`Ja. Een woning die nog wordt gebouwd en die naar verwachting binnen drie jaar het hoofdverblijf wordt, kan als eigen woning gelden. De rente over de eigenwoningschuld is dan in die periode al aftrekbaar. Wordt de woning niet binnen die termijn betrokken, dan kan aftrek alsnog vervallen.`,tags:['nieuwbouw','aanbouw','renteaftrek'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-008',thema:'fiscaal-eigen-woning',vraag:'Is de rente over een lening voor een bouwkavel aftrekbaar?',antwoord:`Dat kan, als op de kavel een woning wordt gebouwd die naar verwachting binnen drie jaar het hoofdverblijf wordt. Blijft de bouw uit of wordt de woning niet tijdig betrokken, dan vervalt de aftrek. Leg de bouwplannen en planning vast in het dossier.`,tags:['bouwkavel','grond','renteaftrek'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-009',thema:'fiscaal-eigen-woning',vraag:'Wat geldt voor een woning die na aankoop eerst wordt verbouwd voordat de klant er gaat wonen?',antwoord:`Een gekochte woning die leegstaat in afwachting van bewoning, kan maximaal drie jaar als eigen woning gelden. Voorwaarde is dat de klant de bedoeling heeft om er binnen die periode zijn hoofdverblijf te vestigen. Tijdelijke verhuur in die periode doorbreekt dit. Leg de verhuisplanning vast.`,tags:['verbouwing','leegstand','nieuwe woning'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-010',thema:'fiscaal-eigen-woning',vraag:'Kan een recreatiewoning een eigen woning zijn?',antwoord:`Fiscaal draait het om het feitelijke hoofdverblijf. Woont een klant duurzaam in een recreatiewoning, dan kan die in beginsel een eigen woning zijn. Let op de publiekrechtelijke regels: permanente bewoning is vaak niet toegestaan. Controleer ook de acceptatievoorwaarden van de geldverstrekker en leg de afweging vast.`,tags:['recreatiewoning','hoofdverblijf','bestemmingsplan'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-011',thema:'fiscaal-eigen-woning',vraag:'Kan een lening voor een warmtepomp of aansluiting op een warmtenet eigenwoningschuld zijn?',antwoord:`Ja, als het gaat om een verbetering van de eigen woning en de installatie vast met de woning is verbonden. De lening moet dan voldoen aan de aflossingseis. Subsidies kunnen de bestede kosten verlagen, wat gevolgen heeft voor de hoogte van de eigenwoningschuld. Bewaar offertes, facturen en subsidiebeschikkingen.`,tags:['warmtepomp','verduurzaming','verbetering'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-012',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant in een verpleeghuis wordt opgenomen?',antwoord:`Blijft de fiscale partner in de woning wonen, dan blijft het de eigen woning. Is de klant alleenstaand en komt de woning leeg te staan, dan kan die onder voorwaarden nog tijdelijk eigen woning blijven, bijvoorbeeld als hij te koop staat. Laat de exacte voorwaarden en termijnen toetsen bij de Belastingdienst of een fiscalist.`,tags:['zorginstelling','leegstand','senioren'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-013',thema:'fiscaal-eigen-woning',vraag:'Is een woning die deels als praktijkruimte wordt gebruikt volledig eigen woning?',antwoord:`Niet altijd. Behoort een deel van de woning tot het ondernemingsvermogen, dan valt dat deel niet onder de eigenwoningregeling. De schuld moet dan worden toegerekend aan het woongedeelte en het zakelijke gedeelte. Laat de splitsing door de boekhouder of fiscalist vastleggen.`,tags:['ondernemer','praktijkruimte','splitsing'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-014',thema:'fiscaal-eigen-woning',vraag:'Kan een woning in een eigen BV een eigen woning zijn?',antwoord:`Nee. Een woning die eigendom is van een BV, behoort niet de klant toe. De klant heeft dan geen eigen woning in box 1 en geen renteaftrek. Wel kunnen er fiscale gevolgen zijn in de BV en in box 2, zoals een onzakelijke huurprijs.`,tags:['bv','eigendom','box 2'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-015',thema:'fiscaal-eigen-woning',vraag:'Wat geldt voor een appartementsrecht?',antwoord:`Een appartementsrecht kan gewoon een eigen woning zijn als het appartement het hoofdverblijf is. De bijdragen aan de VvE zijn niet aftrekbaar, ook niet het deel dat naar het onderhoudsfonds gaat. Een lening voor de aankoop van het appartement kan eigenwoningschuld zijn.`,tags:['appartement','vve','eigen woning'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-016',thema:'fiscaal-eigen-woning',vraag:'Is rente over een lening die de VvE afsluit aftrekbaar voor de eigenaar?',antwoord:`In de regel niet. Bij een lening van de VvE is de VvE de schuldenaar en niet de individuele eigenaar. De eigenaar betaalt een bijdrage, geen rente op een eigen schuld. Controleer de actuele standpunten bij de Belastingdienst en leg dit vast als het in het advies speelt.`,tags:['vve','lening','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-017',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt het als een klant kamers verhuurt in de eigen woning?',antwoord:`Bij kamerverhuur in de eigen woning kan de kamerverhuurvrijstelling gelden. Wordt aan de voorwaarden voldaan, dan blijft de hele woning eigen woning en is de huur onbelast. Wordt niet voldaan, dan valt het verhuurde deel in box 3 en is de rente voor dat deel niet aftrekbaar. Zie de Belastingdienst voor het actuele grensbedrag en de voorwaarden.`,tags:['kamerverhuur','vrijstelling','verhuur'],bron:'Belastingdienst'},
 {id:'fex-018',thema:'fiscaal-eigen-woning',vraag:'Wat is het gevolg als de kamerverhuurvrijstelling niet van toepassing is?',antwoord:`Het verhuurde deel van de woning valt dan in box 3. De rente over de eigenwoningschuld is alleen aftrekbaar voor het deel dat zelf wordt bewoond. Het eigenwoningforfait wordt ook naar verhouding berekend. Leg de verdeling vast en laat de aangifte hierop aansluiten.`,tags:['kamerverhuur','box 3','splitsing'],bron:'Belastingdienst'},
 {id:'fex-019',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt het verhuren van de eigen woning tijdens de vakantie belast?',antwoord:`Bij tijdelijke verhuur van de eigen woning, bijvoorbeeld tijdens de vakantie, blijft de woning eigen woning. Een deel van de huuropbrengst wordt dan als inkomen uit eigen woning in box 1 belast. Controleer ook of de geldverstrekker en de VvE de verhuur toestaan.`,tags:['vakantieverhuur','tijdelijke verhuur','box 1'],bron:'Wet IB 2001 art. 3.114'},
 {id:'fex-020',thema:'fiscaal-eigen-woning',vraag:'Speelt de bestemming van het onderpand een rol bij de vraag of een lening eigenwoningschuld is?',antwoord:`Nee. Bepalend is waaraan het geld is besteed, niet welk onderpand zekerheid geeft. Een lening met hypotheek op een vakantiewoning kan eigenwoningschuld zijn als het geld is gebruikt voor de eigen woning. Omgekeerd is een lening op de eigen woning voor een auto geen eigenwoningschuld.`,tags:['bestedingseis','onderpand','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-021',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met een overwaardehypotheek die voor consumptieve doelen wordt gebruikt?',antwoord:`Het deel dat niet aan de eigen woning wordt besteed, is geen eigenwoningschuld. Dat deel valt in box 3 en de rente is niet aftrekbaar. Het blijft wel een schuld met hypotheekrecht op de woning. Splits dit in een apart leningdeel en leg de besteding vast.`,tags:['overwaarde','consumptief','box 3'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-022',thema:'fiscaal-eigen-woning',vraag:'Kan een lening voor zonnepanelen eigenwoningschuld zijn?',antwoord:`Ja, als de zonnepanelen een verbetering van de eigen woning zijn en vast aan de woning zijn verbonden. Ook dan moet de lening voldoen aan de aflossingseis. Bij losse of verplaatsbare installaties is dat minder zeker. Leg vast waaraan het geld is besteed, bijvoorbeeld met facturen.`,tags:['zonnepanelen','verduurzaming','verbetering'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-023',thema:'fiscaal-eigen-woning',vraag:'Is een lening voor inboedel of meubels eigenwoningschuld?',antwoord:`Nee. Inboedel, meubels en losse apparatuur zijn geen verwerving, verbetering of onderhoud van de woning. Een lening voor deze zaken valt in box 3, ook als de lening via de hypotheek loopt. Let op bij een verbouwingsbudget waar ook een keuken of witgoed in zit: vast ingebouwd is iets anders dan los.`,tags:['inboedel','box 3','verbouwing'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-024',thema:'fiscaal-eigen-woning',vraag:'Is een lening voor onderhoud aan de woning aftrekbaar?',antwoord:`Ja. Een lening voor onderhoud of verbetering van de eigen woning kan eigenwoningschuld zijn, mits aan de aflossingseis wordt voldaan. De onderhoudskosten zelf zijn niet aftrekbaar. Bewaar facturen om de besteding te kunnen aantonen.`,tags:['onderhoud','verbetering','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-025',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen de eigenwoningschuld en de hypothecaire inschrijving?',antwoord:`De hypothecaire inschrijving is het bedrag waarvoor de geldverstrekker zekerheid heeft op de woning. De eigenwoningschuld is het deel van de lening dat fiscaal aan de eigen woning is besteed. Een hoge inschrijving zegt dus niets over de renteaftrek. Leg beide bedragen afzonderlijk vast.`,tags:['inschrijving','eigenwoningschuld','onderscheid'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-026',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt een rentekorting van de geldverstrekker voor de renteaftrek?',antwoord:`Alleen de rente die de klant werkelijk betaalt, is aftrekbaar. Een korting, bijvoorbeeld voor een goed energielabel, verlaagt dus de aftrekbare rente. Gebruik in de netto lastberekening de rente na korting. Controleer de voorwaarden van de geldverstrekker voor de duur van de korting.`,tags:['rentekorting','renteaftrek','netto last'],bron:'Belastingdienst'},
 {id:'fex-027',thema:'fiscaal-eigen-woning',vraag:'Is bouwrente bij nieuwbouw aftrekbare hypotheekrente?',antwoord:`Nee, niet als rente. Bouwrente die aan de ontwikkelaar of aannemer wordt betaald, hoort bij de verwervingskosten van de woning. Die kosten kunnen wel worden meegefinancierd als eigenwoningschuld. Onderscheid dit van de rente die aan de geldverstrekker wordt betaald.`,tags:['bouwrente','nieuwbouw','verwervingskosten'],bron:'Belastingdienst'},
 {id:'fex-028',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen verwervingskosten en financieringskosten?',antwoord:`Verwervingskosten zijn kosten om de woning te kopen, zoals overdrachtsbelasting, notariskosten voor de leveringsakte en makelaarskosten. Die zijn niet direct aftrekbaar, maar mogen worden meegefinancierd binnen de eigenwoningschuld. Financieringskosten zijn kosten voor het afsluiten van de lening en zijn direct aftrekbaar in het jaar van betaling.`,tags:['verwervingskosten','financieringskosten','kosten koper'],bron:'Belastingdienst'},
 {id:'fex-029',thema:'fiscaal-eigen-woning',vraag:'Zijn advieskosten voor de hypotheek aftrekbaar?',antwoord:`Advies- en bemiddelingskosten die betrekking hebben op het afsluiten van de hypotheek, zijn financieringskosten en daarom aftrekbaar. Kosten voor een aankoopmakelaar zijn geen financieringskosten, maar verwervingskosten. Zorg dat de nota de werkzaamheden duidelijk splitst.`,tags:['advieskosten','financieringskosten','nota'],bron:'Belastingdienst'},
 {id:'fex-030',thema:'fiscaal-eigen-woning',vraag:'Is de borgtochtprovisie voor NHG aftrekbaar?',antwoord:`Ja. De eenmalige borgtochtprovisie voor de Nationale Hypotheek Garantie geldt als financieringskosten. Die kosten zijn aftrekbaar in het jaar waarin ze zijn betaald. Zie NHG voor het actuele percentage en de NHG-grens.`,tags:['nhg','borgtochtprovisie','financieringskosten'],bron:'NHG'},
 {id:'fex-031',thema:'fiscaal-eigen-woning',vraag:'Zijn taxatiekosten aftrekbaar?',antwoord:`Taxatiekosten die nodig zijn voor het verkrijgen van de hypotheek, gelden als financieringskosten en zijn aftrekbaar. Een taxatie die alleen voor de klant zelf is bedoeld, valt daar niet onder. Leg in het dossier vast waarvoor de taxatie is gemaakt.`,tags:['taxatie','financieringskosten','aftrek'],bron:'Belastingdienst'},
 {id:'fex-032',thema:'fiscaal-eigen-woning',vraag:'In welk jaar zijn financieringskosten aftrekbaar?',antwoord:`Financieringskosten zijn aftrekbaar in het jaar waarin ze zijn betaald. Bij aankoop eind december kan dat dus een ander jaar zijn dan het jaar van de eerste maandlast. Controleer de afrekening van de notaris op datum van betaling.`,tags:['financieringskosten','tijdstip','aangifte'],bron:'Belastingdienst'},
 {id:'fex-033',thema:'fiscaal-eigen-woning',vraag:'Zijn kosten voor het oversluiten van de hypotheek aftrekbaar?',antwoord:`Kosten die verband houden met het afsluiten van de nieuwe lening, zoals advies, taxatie en notariskosten voor de hypotheekakte, zijn financieringskosten. Die zijn aftrekbaar als de nieuwe lening eigenwoningschuld is. Voor het deel van de lening dat in box 3 valt, zijn ze niet aftrekbaar in box 1.`,tags:['oversluiten','financieringskosten','herfinanciering'],bron:'Belastingdienst'},
 {id:'fex-034',thema:'fiscaal-eigen-woning',vraag:'Mag meegefinancierde boeterente onder de eigenwoningschuld vallen?',antwoord:`Een lening om de boeterente bij oversluiten te betalen kan eigenwoningschuld zijn. Dan moet die lening wel voldoen aan de aflossingseis. Wordt de boeterente in de rente verwerkt, dan is er geen afzonderlijke lening. Leg de gekozen constructie en de fiscale behandeling vast.`,tags:['boeterente','oversluiten','aflossingseis'],bron:'Belastingdienst'},
 {id:'fex-035',thema:'fiscaal-eigen-woning',vraag:'Is de rente over de periode tussen passeren en de eerste maandtermijn aftrekbaar?',antwoord:`Ja. Rente die bij het passeren via de notaris wordt verrekend, is rente over de eigenwoningschuld. Die is aftrekbaar in het jaar waarin deze is betaald. Controleer de nota van afrekening, zodat deze rente niet wordt vergeten in de aangifte.`,tags:['passeren','notaris','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-036',thema:'fiscaal-eigen-woning',vraag:'Is de rente aftrekbaar als de woning eerst contant is betaald en later wordt gefinancierd?',antwoord:`Dat is een risico. De lening moet zijn aangegaan voor de verwerving, verbetering of het onderhoud van de woning. Bij financiering achteraf is dat verband lastig aan te tonen. Laat dit vooraf toetsen door de Belastingdienst of een fiscalist en leg de onderbouwing vast.`,tags:['achteraf financieren','bestedingseis','risico'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-037',thema:'fiscaal-eigen-woning',vraag:'Is een lening voor aankoop van de grond onder erfpacht eigenwoningschuld?',antwoord:`Ja. Het afkopen van erfpacht of het kopen van de grond hoort bij de verwerving van de eigen woning. Een lening daarvoor kan eigenwoningschuld zijn als aan de aflossingseis wordt voldaan. Na de afkoop vervalt de canon, dus ook de aftrek daarvan.`,tags:['erfpacht','afkoop','eigenwoningschuld'],bron:'Belastingdienst'},
 {id:'fex-038',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt het als erfpacht voor lange tijd vooruit wordt afgekocht?',antwoord:`Bij een afkoop voor een bepaalde periode is geen sprake van jaarlijkse canon. De betaalde afkoopsom is dan geen aftrekbare erfpachtcanon. Een lening om de afkoopsom te betalen kan wel eigenwoningschuld zijn. Laat bij twijfel de fiscale kwalificatie toetsen.`,tags:['erfpacht','afkoopsom','canon'],bron:'Belastingdienst'},
 {id:'fex-039',thema:'fiscaal-eigen-woning',vraag:'Kan het eigenwoningforfait lager zijn bij een woning in aanbouw?',antwoord:`Voor een woning in aanbouw zonder WOZ-waarde voor de afgebouwde woning, geldt een aparte benadering. Kijk voor de juiste waarde naar de aanwijzingen in de aangifte en de WOZ-beschikking. Voorkom dat de klant een verkeerde waarde invult.`,tags:['eigenwoningforfait','nieuwbouw','woz'],bron:'Belastingdienst'},
 {id:'fex-040',thema:'fiscaal-eigen-woning',vraag:'Moet het eigenwoningforfait naar rato worden berekend bij aankoop in de loop van het jaar?',antwoord:`Ja. Het eigenwoningforfait wordt berekend over de periode waarin de woning in dat jaar eigen woning was. Bij aankoop of verkoop halverwege het jaar telt dus maar een deel van het jaar. Hetzelfde geldt voor de rente: alleen de rente over die periode is aftrekbaar.`,tags:['eigenwoningforfait','tijdsevenredig','aankoop'],bron:'Belastingdienst'},
 {id:'fex-041',thema:'fiscaal-eigen-woning',vraag:'Welk eigenwoningforfait geldt voor een woning die leeg te koop staat?',antwoord:`Ook een leegstaande woning die nog als eigen woning geldt, heeft een eigenwoningforfait. Het forfait wordt berekend op basis van de WOZ-waarde, net als bij een bewoonde woning. Houd hier rekening mee in de netto maandlast tijdens de dubbele woonlasten.`,tags:['eigenwoningforfait','leegstand','dubbele lasten'],bron:'Belastingdienst'},
 {id:'fex-042',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant een woning koopt voor kinderen die er gaan wonen?',antwoord:`Een woning die door een kind als hoofdverblijf wordt gebruikt, is geen eigen woning van de ouder. Voor de ouder valt de woning met de schuld in box 3. Rente is dan niet aftrekbaar. Bekijk alternatieven, zoals een lening of schenking aan het kind, en leg de afweging vast.`,tags:['ouders','kinderen','box 3'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-043',thema:'fiscaal-eigen-woning',vraag:'Kan een student zijn kamer of studio als eigen woning hebben?',antwoord:`Ja, als de student eigenaar is en de woning duurzaam zijn hoofdverblijf is. Dan gelden de normale regels voor eigenwoningschuld en aflossingseis. Is de ouder eigenaar en woont het kind er, dan is het voor de ouder geen eigen woning.`,tags:['student','hoofdverblijf','eigendom'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-044',thema:'fiscaal-eigen-woning',vraag:'Telt een woning in het buitenland als eigen woning voor een inwoner van Nederland?',antwoord:`Een woning in het buitenland kan een eigen woning zijn als het de hoofdverblijfplaats is. Vaak spelen dan belastingverdragen en regels ter voorkoming van dubbele belasting. Laat deze situatie altijd door een fiscalist met internationale kennis beoordelen.`,tags:['buitenland','verdrag','hoofdverblijf'],bron:'Belastingdienst'},
 {id:'fex-045',thema:'fiscaal-eigen-woning',vraag:'Kan een buitenlands belastingplichtige hypotheekrente aftrekken in Nederland?',antwoord:`Dat kan in bepaalde gevallen, bijvoorbeeld als de klant kwalificeert als buitenlands belastingplichtige die aan de voorwaarden voldoet. De regels zijn complex en hangen af van woonland en inkomen. Verwijs naar een fiscalist en leg vast dat de fiscale aftrek niet is meegenomen tot die toets is gedaan.`,tags:['buitenlands belastingplichtig','grensarbeider','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-046',thema:'fiscaal-eigen-woning',vraag:'Wanneer eindigt de eigenwoningstatus bij verhuizing naar een huurwoning?',antwoord:`Als de klant de woning verlaat en die leeg te koop zet, kan de woning nog tot drie jaar eigen woning blijven. Wordt de woning verhuurd of niet te koop gezet, dan stopt de status direct. Leg de verkoopopdracht en de datum van verhuizing vast.`,tags:['verhuizing','leegstand','te koop'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-047',thema:'fiscaal-eigen-woning',vraag:'Telt een woning die leeg staat maar niet te koop staat nog als eigen woning?',antwoord:`Nee, in het algemeen niet. De leegstandsregeling geldt alleen als de woning leeg staat en te koop staat. Staat de woning leeg zonder verkoopintentie, dan valt deze in box 3. Leg vast vanaf wanneer de woning te koop staat, bijvoorbeeld via de makelaarsopdracht.`,tags:['leegstand','verkoop','box 3'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-048',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er fiscaal als een verbouwing deels met een verzekeringsuitkering wordt betaald?',antwoord:`Alleen het deel van de lening dat werkelijk aan de woning is besteed, kan eigenwoningschuld zijn. Betaalt een verzekeringsuitkering een deel van het herstel, dan is voor dat deel geen lening nodig. Een hogere lening valt voor het meerdere in box 3. Leg de kosten en de uitkering naast elkaar vast.`,tags:['verzekeringsuitkering','herstel','besteding'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-049',thema:'fiscaal-eigen-woning',vraag:'Wat is een veelgemaakte fout bij de leegstandsregeling?',antwoord:`Een veelgemaakte fout is tijdelijk verhuren van de leegstaande woning zonder de fiscale gevolgen te kennen. Tijdens de verhuur valt de woning in box 3. Een andere fout is te laat te koop zetten. Bespreek beide punten bij een verhuisadvies en leg dit vast.`,tags:['leegstand','verhuur','fout'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-050',thema:'fiscaal-eigen-woning',vraag:'Hoe toon je aan dat een leegstaande woning echt te koop staat?',antwoord:`Bewaar de verkoopopdracht aan de makelaar, de advertenties en de vraagprijs. Een realistische vraagprijs ondersteunt dat er een serieuze verkoopintentie is. Leg ook vast wanneer de woning te koop is gezet. Zo kan de klant bij een controle de leegstandsregeling onderbouwen.`,tags:['leegstand','te koop','bewijs'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-051',thema:'fiscaal-eigen-woning',vraag:'Welk bedrag geldt als startpunt voor het annuïtaire schema bij de aflossingseis?',antwoord:`Het schema gaat uit van de hoofdsom van de eigenwoningschuld bij het aangaan van de lening. Daarmee wordt berekend hoeveel er minimaal per periode moet worden afgelost. Het gaat om een minimum: meer aflossen mag altijd. Bewaar het schema van de geldverstrekker in het dossier.`,tags:['aflossingseis','annuïtair','hoofdsom'],bron:'Wet IB 2001'},
 {id:'fex-052',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met het aflossingsschema als de rente wijzigt?',antwoord:`Bij een renteherziening wordt de annuïteit opnieuw berekend over de resterende looptijd. Het fiscale minimum aan aflossing kan daardoor veranderen. De resterende looptijd blijft gekoppeld aan de oorspronkelijke 360 maanden. Controleer na een renteherziening of het nieuwe schema nog aansluit.`,tags:['renteherziening','annuïteit','looptijd'],bron:'Wet IB 2001'},
 {id:'fex-053',thema:'fiscaal-eigen-woning',vraag:'Voldoet een lineaire hypotheek automatisch aan de aflossingseis?',antwoord:`Een lineaire hypotheek met een looptijd van maximaal 360 maanden lost sneller af dan een annuïtaire. Daarmee voldoet die aan de aflossingseis. Let op bij een langere looptijd of een aflossingsvrije periode: dan wordt niet voldaan. Controleer altijd de looptijd in de offerte.`,tags:['lineair','aflossingseis','looptijd'],bron:'Wet IB 2001'},
 {id:'fex-054',thema:'fiscaal-eigen-woning',vraag:'Mag een eigenwoningschuld een aflossingsvrije startperiode hebben?',antwoord:`Nee. Voor eigenwoningschuld vanaf 2013 moet vanaf de start ten minste annuïtair worden afgelost. Een aflossingsvrije periode, ook als die kort is, past daar niet in. Het aflossingsvrije deel valt in box 3.`,tags:['aflossingsvrij','aflossingseis','box 3'],bron:'Wet IB 2001'},
 {id:'fex-055',thema:'fiscaal-eigen-woning',vraag:'Kan een hypotheek met een looptijd langer dan 30 jaar deels eigenwoningschuld zijn?',antwoord:`Een lening met een looptijd langer dan 360 maanden voldoet niet aan de aflossingseis voor eigenwoningschuld. Er zijn producten met een langere looptijd, maar dan vervalt de renteaftrek op dat deel. Bespreek dit expliciet en leg vast dat de klant de fiscale gevolgen kent.`,tags:['looptijd','40 jaar','aflossingseis'],bron:'Wet IB 2001'},
 {id:'fex-056',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt een extra aflossing verwerkt in het fiscale schema?',antwoord:`Na een extra aflossing mag de klant de maandlast verlagen of de looptijd verkorten. Fiscaal geldt dat het resterende bedrag binnen de oorspronkelijke 360 maanden moet worden afgelost. Controleer de voorwaarden van de geldverstrekker.`,tags:['extra aflossing','schema','looptijd'],bron:'Wet IB 2001'},
 {id:'fex-057',thema:'fiscaal-eigen-woning',vraag:'Wat is het risico van een betalingsregeling bij een eigenwoningschuld?',antwoord:`Een betalingsregeling waarbij de aflossing wordt opgeschort, kan leiden tot een aflossingsachterstand. Wordt die niet tijdig ingehaald, dan kan het betreffende deel zijn status als eigenwoningschuld verliezen. Bespreek dit met de klant en de geldverstrekker voordat de regeling ingaat.`,tags:['betalingsregeling','achterstand','risico'],bron:'Wet IB 2001'},
 {id:'fex-058',thema:'fiscaal-eigen-woning',vraag:'Wie bewaakt of de klant aan de aflossingseis voldoet?',antwoord:`De geldverstrekker moet jaarlijks gegevens over de lening aan de Belastingdienst doorgeven. De klant blijft zelf verantwoordelijk voor een juiste aangifte. Bij familieleningen ligt de bewaking volledig bij de klant. Wijs de klant hierop en leg dat vast.`,tags:['aflossingseis','renseignering','verantwoordelijkheid'],bron:'Belastingdienst'},
 {id:'fex-059',thema:'fiscaal-eigen-woning',vraag:'Voldoet een spaarhypotheek die na 2012 is afgesloten aan de aflossingseis?',antwoord:`Een nieuwe spaarhypotheek zonder overgangsrecht voldoet niet aan de aflossingseis. De lening zelf wordt dan niet tijdens de looptijd afgelost. Zonder overgangsrecht valt zo een lening in box 3. Alleen met overgangsrecht kan een gekoppeld spaar- of beleggingsproduct nog fiscaal vrijgesteld zijn.`,tags:['spaarhypotheek','overgangsrecht','aflossingseis'],bron:'Wet IB 2001'},
 {id:'fex-060',thema:'fiscaal-eigen-woning',vraag:'Kan een leningdeel zowel eigenwoningschuld als box 3-schuld bevatten?',antwoord:`Ja. Een leningdeel kan voor een deel eigenwoningschuld zijn en voor een deel box 3-schuld. Dat gebeurt bijvoorbeeld als een deel is besteed aan consumptieve doelen. In de praktijk is het verstandig de delen administratief te splitsen. Rente en aflossing worden dan naar verhouding toegerekend.`,tags:['splitsing','box 3','leningdeel'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-061',thema:'fiscaal-eigen-woning',vraag:'Hoe rekent de Belastingdienst rente toe bij een gemengde lening?',antwoord:`Bij een lening die gedeeltelijk eigenwoningschuld is, wordt de rente naar verhouding toegerekend. Alleen het deel dat bij de eigenwoningschuld hoort, is aftrekbaar in box 1. Een aparte administratie per leningdeel maakt de aangifte eenvoudiger en controleerbaar.`,tags:['rentetoerekening','gemengde lening','box 1'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-062',thema:'fiscaal-eigen-woning',vraag:'Mag een klant zelf kiezen welk leningdeel als eerste wordt afgelost?',antwoord:`Bij een extra aflossing bepaalt de geldverstrekker binnen het contract vaak waar de aflossing op valt. Fiscaal is het meestal gunstig om eerst box 3-schuld af te lossen, omdat daarover geen renteaftrek is. Controleer de voorwaarden van de geldverstrekker en leg de keuze vast.`,tags:['extra aflossing','box 3','volgorde'],bron:'Belastingdienst'},
 {id:'fex-063',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant de maandlast een paar maanden niet betaalt?',antwoord:`Dan ontstaat er een betalingsachterstand en mogelijk ook een fiscale aflossingsachterstand. Voor de aflossingseis telt of de schuld hoger is dan volgens het minimale schema. Wordt de achterstand niet tijdig ingehaald, dan kan het betreffende deel box 3-schuld worden. Laat de termijnen voor inhalen per geval controleren.`,tags:['achterstand','aflossingseis','betalingsproblemen'],bron:'Wet IB 2001'},
 {id:'fex-064',thema:'fiscaal-eigen-woning',vraag:'Wat betekent de dertigjaarstermijn voor de renteaftrek per leningdeel?',antwoord:`De renteaftrek geldt per eigenwoningschuld maximaal 360 maanden. Bij meerdere leningdelen kan elke schuld een eigen termijn hebben. Voor schulden met overgangsrecht liep de termijn vanaf het moment van ontstaan, maar niet eerder dan 2001. Houd per leningdeel de startdatum bij.`,tags:['dertig jaar','looptijd','administratie'],bron:'Wet IB 2001'},
 {id:'fex-065',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als de dertigjaarstermijn van een oude lening afloopt terwijl er nog schuld is?',antwoord:`Na afloop van de termijn is de rente over die schuld niet meer aftrekbaar. De resterende schuld gaat dan naar box 3. Klanten met leningen van rond 2001 lopen hier de komende jaren tegenaan. Signaleer dit tijdig en bespreek aflossen of herfinancieren.`,tags:['dertig jaar','afloop','box 3'],bron:'Wet IB 2001'},
 {id:'fex-066',thema:'fiscaal-eigen-woning',vraag:'Begint de dertigjaarstermijn opnieuw bij oversluiten?',antwoord:`Nee. Bij oversluiten van een eigenwoningschuld loopt de oorspronkelijke termijn door. Alleen een echt nieuw bedrag, bijvoorbeeld voor verbouwing, krijgt een eigen nieuwe termijn. Leg de oorspronkelijke ingangsdatum per leningdeel vast bij elke wijziging.`,tags:['oversluiten','dertig jaar','ingangsdatum'],bron:'Wet IB 2001'},
 {id:'fex-067',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de dertigjaarstermijn bij verhuizing?',antwoord:`De resterende looptijd van de oude eigenwoningschuld gaat mee naar de nieuwe woning, voor zover de schuld wordt voortgezet. Het deel dat extra wordt geleend krijgt een nieuwe termijn van 360 maanden. In de praktijk zijn er daardoor meerdere einddata. Zet die in het adviesrapport.`,tags:['verhuizing','looptijd','meeneemregeling'],bron:'Wet IB 2001'},
 {id:'fex-068',thema:'fiscaal-eigen-woning',vraag:'Waarom is het verloop van leningdelen belangrijk bij een nieuwe hypotheek?',antwoord:`De fiscale historie van elk leningdeel bepaalt overgangsrecht, resterende looptijd en aflossingsschema. Zonder die gegevens kan de adviseur de nieuwe lening niet goed fiscaal inrichten. Vraag bij de klant en vorige geldverstrekker de historie op en bewaar die in het dossier.`,tags:['fiscale historie','leningdelen','dossier'],bron:'Belastingdienst'},
 {id:'fex-069',thema:'fiscaal-eigen-woning',vraag:'Mag een hypotheek met verhuisregeling zonder meer worden meegenomen?',antwoord:`De fiscale status van het meegenomen deel hangt af van de fiscale historie en van de nieuwe eigenwoningschuld. Als de nieuwe eigenwoningschuld lager is, past niet alles meer binnen box 1. Controleer de voorwaarden van de geldverstrekker voor de verhuisregeling en maak een fiscale toets.`,tags:['verhuisregeling','meenemen','fiscale toets'],bron:'Belastingdienst'},
 {id:'fex-070',thema:'fiscaal-eigen-woning',vraag:'Is rente over een hypotheek aftrekbaar als de geldverstrekker een buitenlandse partij is?',antwoord:`Ja, als de lening aan alle voorwaarden voor eigenwoningschuld voldoet. Bij een buitenlandse geldverstrekker zonder Nederlandse gegevensuitwisseling moet de klant mogelijk zelf gegevens aanleveren. Controleer de informatieplicht en leg vast welke gegevens zijn verstrekt.`,tags:['buitenlandse geldverstrekker','informatieplicht','renteaftrek'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-071',thema:'fiscaal-eigen-woning',vraag:'Kan een lening bij de eigen BV eigenwoningschuld zijn?',antwoord:`Ja, een lening van de eigen BV kan eigenwoningschuld zijn als aan de voorwaarden wordt voldaan. Denk aan een zakelijke rente, een aflossingsschema volgens de aflossingseis en de informatieplicht. Let ook op de regels voor excessief lenen bij de eigen vennootschap. Laat dit toetsen door een fiscalist.`,tags:['eigen bv','excessief lenen','zakelijke rente'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-072',thema:'fiscaal-eigen-woning',vraag:'Hoe leg je uit wanneer de klant het fiscale voordeel van de renteaftrek ontvangt?',antwoord:`Zonder voorlopige aanslag ontvangt de klant het voordeel pas na de aangifte over het jaar. Met een voorlopige aanslag krijgt hij het maandelijks. In de eerste maanden na aankoop kan de netto last daardoor tijdelijk hoger zijn. Neem dit mee in de liquiditeitsplanning van de klant.`,tags:['voorlopige aanslag','liquiditeit','uitleg'],bron:'Belastingdienst'},
 {id:'fex-073',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt een zakelijke rente bij een familielening bepaald?',antwoord:`De rente moet passen bij wat een onafhankelijke geldverstrekker zou vragen voor een vergelijkbare lening. Factoren zijn looptijd, rentevaste periode en zekerheid. Een recht van hypotheek kan een lagere rente rechtvaardigen. Leg vast hoe de rente is bepaald, bijvoorbeeld met vergelijkbare tarieven.`,tags:['familielening','zakelijke rente','onderbouwing'],bron:'Belastingdienst'},
 {id:'fex-074',thema:'fiscaal-eigen-woning',vraag:'Wat zijn de fiscale gevolgen voor ouders die een lening verstrekken aan een kind?',antwoord:`De vordering op het kind hoort voor de ouders bij de bezittingen in box 3. Hoe het rendement daarop wordt belast, hangt af van het actuele box 3-stelsel. Ouders moeten de lening wel opgeven in hun aangifte. Wijs ook hen op deze verplichting.`,tags:['familielening','ouders','box 3'],bron:'Belastingdienst'},
 {id:'fex-075',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als ouders de rente op een familielening kwijtschelden?',antwoord:`Kwijtschelding van rente of aflossing is een schenking aan het kind. Daarover kan schenkbelasting verschuldigd zijn als de vrijstelling wordt overschreden. Kwijtgescholden rente is bovendien niet betaald en dus niet aftrekbaar. Leg vast dat schenkingen apart worden gedocumenteerd.`,tags:['kwijtschelding','schenking','familielening'],bron:'Successiewet 1956'},
 {id:'fex-076',thema:'fiscaal-eigen-woning',vraag:'Mag een kind de rente op een familielening pas aan het eind van het jaar betalen?',antwoord:`Rente is aftrekbaar in het jaar van betaling. Betaalt het kind de rente pas na afloop van het jaar, dan schuift de aftrek mee. Afspraken over het betaalmoment staan in de leningovereenkomst. Adviseer om rente en aflossing periodiek en aantoonbaar via de bank te betalen.`,tags:['familielening','betaalmoment','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-077',thema:'fiscaal-eigen-woning',vraag:'Welke gegevens moet de klant opgeven bij een familielening?',antwoord:`De klant moet in de aangifte gegevens van de lening en de geldverstrekker opgeven. Denk aan naam, adres, burgerservicenummer, het begin- en eindbedrag en de betaalde rente. Gebeurt dat niet tijdig, dan kan de lening haar status als eigenwoningschuld verliezen. Leg vast dat de klant hierop is gewezen.`,tags:['informatieplicht','familielening','aangifte'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-078',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als de informatieplicht bij een familielening wordt vergeten?',antwoord:`Zonder de vereiste gegevens kan de lening niet als eigenwoningschuld gelden. De Belastingdienst geeft eerst een gelegenheid om de gegevens alsnog aan te leveren. Wordt daaraan niet voldaan, dan vervalt de renteaftrek over dat jaar. Controleer elk jaar of de gegevens zijn opgegeven.`,tags:['informatieplicht','herstel','renteaftrek'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-079',thema:'fiscaal-eigen-woning',vraag:'Kan een familielening worden gecombineerd met een bancaire hypotheek?',antwoord:`Ja. Een familielening kan naast een bancaire lening worden afgesloten, bijvoorbeeld als tweede leningdeel. De geldverstrekker kan eisen stellen aan zo een lening, zoals een achtergestelde positie of een verklaring. Controleer de voorwaarden van de geldverstrekker en neem de familielening mee in de lastentoets.`,tags:['familielening','combinatie','acceptatie'],bron:'Belastingdienst'},
 {id:'fex-080',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met de maandlast van een familielening in de leencapaciteitstoets?',antwoord:`De maandlast van een familielening telt mee in de toets, tenzij de geldverstrekker andere voorwaarden hanteert. Ook als ouders mondeling toezeggen niet te innen, is er een schuld. Controleer de voorwaarden van de geldverstrekker en leg de verwerking vast.`,tags:['familielening','leencapaciteit','lastentoets'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'fex-081',thema:'fiscaal-eigen-woning',vraag:'Is rente over een lening bij een vriend of kennis aftrekbaar?',antwoord:`Ja, onder dezelfde voorwaarden als bij een familielening. De lening moet zijn besteed aan de eigen woning, voldoen aan de aflossingseis en een zakelijke rente hebben. Ook de informatieplicht geldt. Leg de afspraken schriftelijk vast.`,tags:['particuliere lening','informatieplicht','renteaftrek'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-082',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt een schuldig erkenning bij een lening van ouders?',antwoord:`Bij een schuldig erkenning erkent het kind een schuld aan de ouders, bijvoorbeeld bij een schenking op papier. Als het kind daarover rente betaalt en het geld voor de woning is gebruikt, kan het eigenwoningschuld zijn. Dan gelden ook de aflossingseis en de informatieplicht. Laat dit door een notaris en fiscalist opzetten.`,tags:['schuldig erkenning','ouders','notaris'],bron:'Belastingdienst'},
 {id:'fex-083',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen een rentevaste periode en de looptijd bij de aflossingseis?',antwoord:`De looptijd bepaalt binnen welke termijn de lening volledig moet zijn afgelost. De rentevaste periode bepaalt alleen hoe lang de rente vastligt. Na afloop van de rentevaste periode blijft de oorspronkelijke looptijd gelden. Verwar die twee niet in het adviesrapport.`,tags:['rentevast','looptijd','aflossingseis'],bron:'Wet IB 2001'},
 {id:'fex-084',thema:'fiscaal-eigen-woning',vraag:'Kan een hypotheek met een variabele rente aan de aflossingseis voldoen?',antwoord:`Ja. De aflossingseis stelt eisen aan de aflossing, niet aan het type rente. Bij een variabele rente wordt het annuïtaire schema regelmatig herberekend. Controleer of het schema van de geldverstrekker steeds aansluit bij de resterende looptijd.`,tags:['variabele rente','aflossingseis','annuïteit'],bron:'Wet IB 2001'},
 {id:'fex-085',thema:'fiscaal-eigen-woning',vraag:'Wat zijn veelgemaakte fouten in de aangifte bij de eigen woning?',antwoord:`Veelvoorkomende fouten zijn het aftrekken van rente over box 3-delen, het vergeten van de depotrente en het verkeerd verdelen tussen partners. Ook financieringskosten worden soms in het verkeerde jaar opgenomen. Bied de klant een overzicht per leningdeel aan als hulpmiddel bij de aangifte.`,tags:['aangifte','fouten','controle'],bron:'Belastingdienst'},
 {id:'fex-086',thema:'fiscaal-eigen-woning',vraag:'Hoe controleer je of de vooraf ingevulde aangifte klopt?',antwoord:`De vooraf ingevulde gegevens komen van de geldverstrekker. Die geven niet altijd de fiscale status per leningdeel juist weer, bijvoorbeeld bij gemengde delen of familieleningen. Vergelijk de gegevens met het eigen overzicht van de leningdelen. Adviseer de klant om afwijkingen te corrigeren.`,tags:['vooraf ingevulde aangifte','controle','leningdelen'],bron:'Belastingdienst'},
 {id:'fex-087',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen de jaaropgave van de bank en de fiscale status?',antwoord:`De jaaropgave geeft betaalde rente en de stand van de lening. Of de lening fiscaal eigenwoningschuld is, staat er niet altijd volledig op. Bij oversluiten of verhuizen kan de fiscale status per deel verschillen. Houd daarom een eigen fiscale administratie bij in het dossier.`,tags:['jaaropgave','fiscale status','administratie'],bron:'Belastingdienst'},
 {id:'fex-088',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt de hypotheekrenteaftrek verwerkt in de voorlopige aanslag?',antwoord:`De klant kan een voorlopige aanslag aanvragen om de renteaftrek maandelijks terug te krijgen. Na een wijziging, zoals verhuizen of oversluiten, moet de voorlopige aanslag worden aangepast. Anders kan achteraf een terugbetaling volgen. Wijs de klant op deze stap na passeren.`,tags:['voorlopige aanslag','teruggave','wijziging'],bron:'Belastingdienst'},
 {id:'fex-089',thema:'fiscaal-eigen-woning',vraag:'Moet de voorlopige aanslag worden aangepast na afloop van de rentevaste periode?',antwoord:`Ja, als de nieuwe rente afwijkt van de oude. Bij een lagere rente is de aftrek lager en kan de teruggave te hoog zijn. Adviseer de klant om de voorlopige aanslag aan te passen na een renteherziening. Leg dit advies vast.`,tags:['voorlopige aanslag','renteherziening','teruggave'],bron:'Belastingdienst'},
 {id:'fex-090',thema:'fiscaal-eigen-woning',vraag:'Hoe beïnvloedt het tarief van de aftrek de netto maandlast?',antwoord:`De netto maandlast hangt af van het tarief waartegen de rente wordt afgetrokken. Dat tarief is begrensd en wijzigt per jaar. Gebruik in berekeningen het actuele tarief van de Belastingdienst en geef aan dat de netto last kan veranderen. Leg de gebruikte uitgangspunten vast.`,tags:['netto last','tarief','berekening'],bron:'Belastingdienst'},
 {id:'fex-091',thema:'fiscaal-eigen-woning',vraag:'Waarom daalt de renteaftrek bij een annuïtaire hypotheek over de tijd?',antwoord:`Bij een annuïtaire hypotheek is de bruto maandlast gelijk, maar het rentedeel daalt. Daardoor wordt ook de renteaftrek kleiner en stijgt de netto last. Laat de klant dit verloop zien in de berekening. Dit voorkomt verrassingen na enkele jaren.`,tags:['annuïteit','netto last','verloop'],bron:'Belastingdienst'},
 {id:'fex-092',thema:'fiscaal-eigen-woning',vraag:'Hoe leg je het verschil tussen bruto en netto maandlast uit aan een klant?',antwoord:`De bruto maandlast is wat de klant aan de geldverstrekker betaalt. De netto last is de bruto last min het fiscale voordeel van de renteaftrek, gecorrigeerd voor het eigenwoningforfait. Het fiscale voordeel hangt af van regels die kunnen wijzigen. Leg de uitleg en de uitgangspunten vast.`,tags:['bruto','netto','uitleg'],bron:'Belastingdienst'},
 {id:'fex-093',thema:'fiscaal-eigen-woning',vraag:'Mag een klant de fiscale teruggave gebruiken om de hypotheek af te lossen?',antwoord:`Ja, dat mag altijd. Een extra aflossing verlaagt de schuld en daarmee de toekomstige rente. Bij een lage schuld ten opzichte van het forfait kan de Wet Hillen een rol spelen. Laat de klant de fiscale effecten van extra aflossen zien en leg de keuze vast.`,tags:['teruggave','extra aflossing','wet hillen'],bron:'Belastingdienst'},
 {id:'fex-094',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de Wet Hillen bij een kleine resterende eigenwoningschuld?',antwoord:`Als de aftrekbare kosten lager zijn dan het eigenwoningforfait, kan een aftrek wegens geen of geringe eigenwoningschuld gelden. Die aftrek wordt sinds 2019 in 30 jaar afgebouwd. Een deel van het verschil wordt daardoor wel belast. Laat dit effect zien bij advies over extra aflossen.`,tags:['wet hillen','afbouw','eigenwoningforfait'],bron:'Wet IB 2001 art. 3.123a'},
 {id:'fex-095',thema:'fiscaal-eigen-woning',vraag:'Mag een klant wachten met kopen tot de eigenwoningreserve is vervallen?',antwoord:`Ja. De eigenwoningreserve vervalt na drie jaar. Koopt de klant daarna een woning, dan beperkt de oude reserve de eigenwoningschuld niet meer. Bespreek wel de risico’s van huren of wachten, zoals prijsontwikkeling en woonlasten. Leg de afweging van de klant vast.`,tags:['eigenwoningreserve','wachten','timing'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-096',thema:'fiscaal-eigen-woning',vraag:'Wat is een rekenvoorbeeld van gemengde besteding bij oversluiten?',antwoord:`Stel dat een klant € 200.000 eigenwoningschuld heeft en oversluit naar € 230.000. Van de extra € 30.000 wordt € 20.000 besteed aan een verbouwing en € 10.000 aan een auto. Dan is € 220.000 eigenwoningschuld en € 10.000 box 3-schuld. De nieuwe € 20.000 moet aan de aflossingseis voldoen.`,tags:['rekenvoorbeeld','oversluiten','splitsing'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-097',thema:'fiscaal-eigen-woning',vraag:'Wat is een rekenvoorbeeld van de aftrek bij aankoop halverwege het jaar?',antwoord:`Stel dat de klant de woning per 1 juli koopt. Dan telt voor dat jaar alleen de rente vanaf 1 juli mee en ook het forfait over de helft van het jaar. Financieringskosten die bij passeren zijn betaald, zijn volledig aftrekbaar in dat jaar. Gebruik de actuele percentages van de Belastingdienst voor het forfait.`,tags:['rekenvoorbeeld','aankoop','tijdsevenredig'],bron:'Belastingdienst'},
 {id:'fex-098',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met een hypotheek die bij een andere geldverstrekker deels is ondergebracht?',antwoord:`Een klant kan leningdelen bij verschillende geldverstrekkers hebben. Elk deel heeft eigen voorwaarden en een eigen fiscale historie. Vraag van alle geldverstrekkers de gegevens op en maak één overzicht. Zo voorkom je dat de aflossingseis of het overgangsrecht ongemerkt verkeerd wordt toegepast.`,tags:['meerdere geldverstrekkers','overzicht','fiscale historie'],bron:'Belastingdienst'},
 {id:'fex-099',thema:'fiscaal-eigen-woning',vraag:'Moet een verbouwingslening binnen een bepaalde tijd worden besteed?',antwoord:`De lening moet aantoonbaar worden besteed aan verbetering of onderhoud van de eigen woning. Bij een bouwdepot gelden termijnen van de geldverstrekker. Wordt het geld niet aan de woning besteed, dan is dat deel geen eigenwoningschuld. Bewaar offertes en facturen bij het dossier.`,tags:['verbouwing','besteding','bouwdepot'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-100',thema:'fiscaal-eigen-woning',vraag:'Wat moet in een schriftelijke overeenkomst voor een familielening staan?',antwoord:`Leg in elk geval het leenbedrag, de rente, de looptijd en het aflossingsschema vast. Het schema moet ten minste annuïtair in maximaal 360 maanden aflossen. Noem ook wat er gebeurt bij overlijden, verkoop of betalingsproblemen. Laat beide partijen tekenen en bewaar een kopie in het dossier.`,tags:['familielening','overeenkomst','vastlegging'],bron:'Wet IB 2001'},
 {id:'fex-101',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigenwoningreserve bij een nieuwbouwproject dat vertraging oploopt?',antwoord:`De eigenwoningreserve vervalt drie jaar na de verkoop van de oude woning. Bij vertraging kan de timing van koop- en aanneemovereenkomst en betalingen ten opzichte van die termijn van belang zijn. Laat de gevolgen per situatie toetsen. Leg de planning en de vervaldatum van de reserve vast.`,tags:['nieuwbouw','vertraging','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-102',thema:'fiscaal-eigen-woning',vraag:'Hoe bepaal je de maximale nieuwe eigenwoningschuld met een eigenwoningreserve?',antwoord:`De maximale eigenwoningschuld is de verwervingskosten van de nieuwe woning min de eigenwoningreserve. Bij verwervingskosten van € 450.000 en een reserve van € 142.000 is dat € 308.000. Leent de klant meer, dan valt het meerdere in box 3. Het gaat om een voorbeeld met fictieve bedragen.`,tags:['rekenvoorbeeld','bijleenregeling','maximale schuld'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-103',thema:'fiscaal-eigen-woning',vraag:'Welke stukken heb je nodig om de eigenwoningreserve te berekenen?',antwoord:`Vraag de nota van afrekening van de verkoop, de makelaarsnota en de stand van de lening op de leveringsdatum op. Vraag ook per leningdeel de fiscale status op, zodat je weet welk deel eigenwoningschuld was. Bewaar de stukken en de berekening in het dossier.`,tags:['eigenwoningreserve','stukken','dossier'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-104',thema:'fiscaal-eigen-woning',vraag:'Ontstaat er een eigenwoningreserve als de woning met verlies wordt verkocht?',antwoord:`Nee. Als de verkoopprijs na kosten lager is dan de eigenwoningschuld, is er geen positieve eigenwoningreserve. De eigenwoningreserve kan niet negatief zijn. Er is dan sprake van een restschuld, met eigen fiscale regels afhankelijk van de verkoopdatum.`,tags:['verlies','restschuld','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-105',thema:'fiscaal-eigen-woning',vraag:'Moet de klant ook spaargeld inbrengen bij aankoop van een nieuwe woning?',antwoord:`Fiscaal niet. De bijleenregeling kijkt alleen naar de overwaarde van de vorige eigen woning. Spaargeld of ander vermogen hoeft niet te worden ingebracht om de rente aftrekbaar te houden. De geldverstrekker kan in de acceptatie wel eigen middelen vragen.`,tags:['spaargeld','bijleenregeling','eigen middelen'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-106',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als de klant de overwaarde op een spaarrekening zet en volledig leent?',antwoord:`De eigenwoningschuld is dan beperkt tot de verwervingskosten min de eigenwoningreserve. Het deel dat hij meer leent, is box 3-schuld. Daarover is geen rente aftrekbaar. Maak dit vooraf inzichtelijk en leg de keuze van de klant vast.`,tags:['overwaarde','box 3','keuze'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-107',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant eerst een nieuwe woning koopt en daarna de oude verkoopt?',antwoord:`Ook dan kan de bijleenregeling gevolgen hebben. De overwaarde van de oude woning kan alsnog van invloed zijn op de maximale eigenwoningschuld van de nieuwe woning. Laat de fiscale gevolgen per situatie berekenen voordat de klant definitief beslist. Leg de verwachte verkoopopbrengst en de berekening vast.`,tags:['volgorde','koop voor verkoop','bijleenregeling'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-108',thema:'fiscaal-eigen-woning',vraag:'Kan een klant afstand doen van de eigenwoningreserve?',antwoord:`Nee. De eigenwoningreserve ontstaat van rechtswege bij de vervreemding van de eigen woning. De klant kan er niet voor kiezen om de reserve niet toe te passen. De reserve vervalt alleen door benutting of na afloop van de termijn van drie jaar.`,tags:['eigenwoningreserve','keuze','termijn'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-109',thema:'fiscaal-eigen-woning',vraag:'Kan de eigenwoningreserve worden opgebouwd uit meerdere verkopen?',antwoord:`Ja. Bij elke vervreemding van een eigen woning kan een eigenwoningreserve ontstaan. Die kan samenvallen met een reserve uit een eerdere verkoop. Breng de historie van alle verkopen in kaart bij een klant die vaak is verhuisd en laat de termijnen per verkoop controleren.`,tags:['meerdere verkopen','eigenwoningreserve','historie'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-110',thema:'fiscaal-eigen-woning',vraag:'Ontstaat er een eigenwoningreserve als de woning ophoudt eigen woning te zijn zonder verkoop?',antwoord:`Ja, dat kan. Als de woning ophoudt eigen woning te zijn, bijvoorbeeld door verhuur, kan dat voor de bijleenregeling als vervreemding gelden. Dan wordt gerekend met de waarde in het economisch verkeer. Laat dit fiscaal toetsen bij een advies over verhuur van de oude woning.`,tags:['fictieve vervreemding','verhuur','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-111',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt de eigenwoningreserve verdeeld tussen partners?',antwoord:`De eigenwoningreserve wordt in beginsel per persoon bepaald, op basis van het aandeel in de verkochte woning en de schuld. Bij fiscale partners kunnen bijzondere regels gelden. Laat de verdeling toetsen en leg de eigendomsverhouding en de reserve per partner vast.`,tags:['partners','eigenwoningreserve','verdeling'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-112',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigenwoningreserve als een nieuwe partner meekoopt?',antwoord:`De eigenwoningreserve van de ene partner beperkt alleen diens eigenwoningschuld. De partner zonder reserve kan in beginsel zijn deel volledig financieren als eigenwoningschuld. Let op de verdeling van eigendom en schuld. Leg de berekening per persoon vast.`,tags:['nieuwe partner','eigenwoningreserve','samenwonen'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-113',thema:'fiscaal-eigen-woning',vraag:'Speelt de eigenwoningreserve een rol bij een verbouwing van de huidige woning?',antwoord:`Ja. Als de klant binnen drie jaar na verkoop een nieuwe woning heeft en die verbouwt, wordt eerst de eigenwoningreserve gebruikt. Pas daarboven kan een lening voor de verbouwing eigenwoningschuld zijn. Neem de reserve mee in elke financieringsberekening binnen die periode.`,tags:['verbouwing','eigenwoningreserve','termijn'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-114',thema:'fiscaal-eigen-woning',vraag:'Waarom moet de adviseur de verkoopgegevens van de vorige woning opvragen?',antwoord:`Zonder verkoopgegevens kan de eigenwoningreserve niet worden berekend. Een te hoge eigenwoningschuld leidt tot onterechte renteaftrek en mogelijk een correctie met rente. Vraag de nota van afrekening en de jaaropgave van de oude hypotheek op en bewaar die.`,tags:['dossier','verkoopgegevens','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-115',thema:'fiscaal-eigen-woning',vraag:'Wat is een veelgemaakte fout bij de bijleenregeling?',antwoord:`Een veelgemaakte fout is het vergeten van een verkoop van enkele jaren geleden. Ook wordt de reserve soms berekend zonder aftrek van verkoopkosten, of juist met kosten die er niet bij horen. Gebruik een vaste rekentool en laat de klant bevestigen dat de gegevens volledig zijn.`,tags:['fout','bijleenregeling','controle'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-116',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de bijleenregeling bij een woning in aanbouw?',antwoord:`Ook bij nieuwbouw wordt de maximale eigenwoningschuld berekend met de verwervingskosten min de eigenwoningreserve. Tot de verwervingskosten horen de koop- en aanneemsom en de bijkomende kosten. Meerwerk kan meetellen als het onderdeel van de woning wordt. Leg de opbouw van de kosten vast.`,tags:['nieuwbouw','bijleenregeling','meerwerk'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-117',thema:'fiscaal-eigen-woning',vraag:'Tellen kosten koper mee in de verwervingskosten voor de bijleenregeling?',antwoord:`Ja. Kosten zoals overdrachtsbelasting en notariskosten voor de levering horen bij de verwervingskosten. Die verhogen de maximale eigenwoningschuld. Financieringskosten horen er niet bij, maar zijn wel direct aftrekbaar.`,tags:['kosten koper','verwervingskosten','bijleenregeling'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-118',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen de eigenwoningreserve en de overwaarde?',antwoord:`De overwaarde is in de praktijk vaak de verkoopprijs min de hypotheek. De eigenwoningreserve is een fiscaal begrip: verkoopprijs min verkoopkosten min eigenwoningschuld. Een box 3-deel van de hypotheek telt daarom niet mee. De bedragen kunnen dus verschillen.`,tags:['overwaarde','eigenwoningreserve','begrip'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-119',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de eigenwoningreserve als de oude hypotheek een box 3-deel had?',antwoord:`Bij de berekening van de eigenwoningreserve wordt alleen de eigenwoningschuld afgetrokken. Een box 3-deel verlaagt de reserve dus niet. In de praktijk kan de klant daardoor minder vrij besteedbaar geld hebben dan de reserve doet vermoeden. Bespreek dit bij verhuizing.`,tags:['box 3','eigenwoningreserve','oude hypotheek'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-120',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de reserve als de nieuwe woning goedkoper is dan de oude?',antwoord:`Bij een goedkopere woning kan de reserve groter zijn dan nodig. De maximale eigenwoningschuld wordt dan laag of nul. Een deel van de reserve blijft drie jaar staan voor een eventuele latere aankoop of verbouwing. Leg vast hoeveel reserve overblijft.`,tags:['goedkoper','eigenwoningreserve','restant'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-121',thema:'fiscaal-eigen-woning',vraag:'Geldt overgangsrecht voor een lening waarvan de overeenkomst in 2012 is getekend maar die in 2013 is verstrekt?',antwoord:`Voor die situatie gold een beperkte overgangsregeling, gekoppeld aan een bindende schriftelijke overeenkomst van voor 2013. Of een lening daaronder valt, hangt af van de data en stukken. Laat dit aan de hand van de originele overeenkomsten toetsen en leg de uitkomst vast.`,tags:['overgangsrecht','2012','bindende overeenkomst'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-122',thema:'fiscaal-eigen-woning',vraag:'Kan bestaande eigenwoningschuld weer worden verhoogd na een aflossing?',antwoord:`Nee. Een aflossing op bestaande eigenwoningschuld vermindert het bedrag met overgangsrecht blijvend. Wordt daarna opnieuw geleend, dan is het nieuwe bedrag gewone eigenwoningschuld met aflossingseis. Wijs klanten met overgangsrecht hierop voordat ze extra aflossen.`,tags:['overgangsrecht','aflossing','herleven'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-123',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt een rekenvoorbeeld met overgangsrecht bij verhuizing naar een duurdere woning?',antwoord:`Stel dat een klant € 150.000 aflossingsvrije bestaande eigenwoningschuld heeft. Hij koopt een woning met verwervingskosten van € 300.000 en heeft geen eigenwoningreserve. Dan kan € 150.000 aflossingsvrij blijven als eigenwoningschuld en moet de extra € 150.000 aan de aflossingseis voldoen. Het gaat om fictieve bedragen.`,tags:['rekenvoorbeeld','overgangsrecht','verhuizing'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-124',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met het overgangsrecht bij verhuizing naar een goedkopere woning?',antwoord:`Het overgangsrecht geldt maximaal tot de nieuwe eigenwoningschuld. Is die lager dan de bestaande eigenwoningschuld, dan vervalt het overgangsrecht voor het verschil. Dat deel komt later niet terug. Laat de klant dit effect zien voordat hij beslist.`,tags:['overgangsrecht','goedkoper','verlies'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-125',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt het overgangsrecht als maar één van de partners overgangsrecht heeft?',antwoord:`Het overgangsrecht hoort bij de bestaande eigenwoningschuld van die partner. Kopen partners samen een woning, dan moet per persoon worden bepaald welk deel van de schuld onder het overgangsrecht valt. De andere partner leent onder de aflossingseis. Laat de verdeling toetsen en leg die vast.`,tags:['partners','overgangsrecht','samen kopen'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-126',thema:'fiscaal-eigen-woning',vraag:'Kan een klant met overgangsrecht kiezen om toch annuïtair af te lossen?',antwoord:`Ja, dat mag altijd. Annuïtair aflossen verlaagt wel de bestaande eigenwoningschuld en dus het overgangsrecht. Voor sommige klanten weegt een lagere schuld zwaarder dan het behoud van overgangsrecht. Leg de afweging en de keuze van de klant vast.`,tags:['overgangsrecht','annuïtair','afweging'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-127',thema:'fiscaal-eigen-woning',vraag:'Geldt overgangsrecht ook voor een schuld die na 2012 is overgesloten?',antwoord:`Ja, voor zover de nieuwe lening een bestaande eigenwoningschuld vervangt. Het overgangsrecht gaat dan mee naar de nieuwe lening tot het bedrag van de bestaande schuld. Een verhoging bij het oversluiten valt onder de aflossingseis.`,tags:['overgangsrecht','oversluiten','verhoging'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-128',thema:'fiscaal-eigen-woning',vraag:'Mag bij oversluiten het overgangsrecht over meerdere leningdelen worden verdeeld?',antwoord:`De fiscale status zit aan het bedrag van de bestaande eigenwoningschuld, niet aan één specifiek product. Bij oversluiten kan dit bedrag over leningdelen worden verdeeld, mits het totaal niet hoger is dan de bestaande eigenwoningschuld. Controleer de voorwaarden van de geldverstrekker en leg de verdeling vast.`,tags:['overgangsrecht','leningdelen','verdeling'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-129',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt het overgangsrecht bij een hypotheek die in 2001 al bestond?',antwoord:`Voor schulden die op 1 januari 2001 al bestonden, is de dertigjaarstermijn op die datum gaan lopen. Daardoor eindigt de renteaftrek over die schulden in 2031. Signaleer dit bij klanten met oude leningdelen en bespreek tijdig de gevolgen.`,tags:['2001','dertig jaar','overgangsrecht'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-130',thema:'fiscaal-eigen-woning',vraag:'Wat is een KEW en hoe verhoudt die zich tot het overgangsrecht?',antwoord:`Een kapitaalverzekering eigen woning is alleen nog fiscaal vrijgesteld als die op 31 december 2012 al bestond. Nieuwe polissen na die datum hebben geen vrijstelling meer. De polis mag onder voorwaarden worden voortgezet bij verhuizing. Controleer de voorwaarden van de verzekeraar.`,tags:['kew','overgangsrecht','polis'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-131',thema:'fiscaal-eigen-woning',vraag:'Wat is de bandbreedte bij een kapitaalverzekering eigen woning?',antwoord:`De hoogste premie in een jaar mag niet hoger zijn dan tien keer de laagste premie in een ander jaar. Wordt hieraan niet voldaan, dan kan de vrijstelling vervallen. Let hierop bij premiewijzigingen of premievrij maken. Laat de verzekeraar bevestigen dat de polis blijft voldoen.`,tags:['kew','bandbreedte','premie'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-132',thema:'fiscaal-eigen-woning',vraag:'Hoe lang moet een KEW lopen om voor de vrijstelling in aanmerking te komen?',antwoord:`Voor de vrijstelling moet er ten minste vijftien jaar premie zijn betaald. Voor een hogere vrijstelling geldt een langere looptijd. Zie de Belastingdienst voor de actuele vrijstellingsbedragen. Controleer de premiehistorie van de polis voordat je advies geeft over afkoop.`,tags:['kew','looptijd','vrijstelling'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-133',thema:'fiscaal-eigen-woning',vraag:'Mag een klant meerdere KEW-polissen hebben?',antwoord:`Ja. De vrijstelling geldt wel per persoon voor alle kapitaalverzekeringen, spaarrekeningen en beleggingsrechten eigen woning samen. Er is dus één vrijstelling voor het totaal. Breng alle polissen en rekeningen in kaart voordat je over uitkering of afkoop adviseert.`,tags:['kew','meerdere polissen','vrijstelling'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-134',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met een KEW als de klant de woning verkoopt en gaat huren?',antwoord:`Het overgangsrecht voor de polis kan blijven bestaan als de polis wordt voortgezet. Wordt binnen de geldende termijn geen nieuwe eigen woning gekocht, dan kunnen de fiscale voordelen vervallen. Controleer de voorwaarden van de verzekeraar en de fiscale termijnen en leg die vast.`,tags:['kew','huren','verkoop'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-135',thema:'fiscaal-eigen-woning',vraag:'Wat moet er gebeuren met de uitkering van een KEW?',antwoord:`De uitkering moet worden gebruikt om de eigenwoningschuld af te lossen. Alleen dan geldt de vrijstelling volledig. Is de uitkering hoger dan de eigenwoningschuld, dan kan het meerdere belast zijn. Plan de uitkeringsdatum en de aflossing samen met de geldverstrekker.`,tags:['kew','uitkering','aflossing'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-136',thema:'fiscaal-eigen-woning',vraag:'Kan een spaarrekening eigen woning nog worden geopend?',antwoord:`Nee, nieuwe spaarrekeningen eigen woning zijn sinds 2013 niet meer fiscaal vrijgesteld. Alleen rekeningen die op 31 december 2012 al bestonden, vallen onder het overgangsrecht. Voor de bestaande rekening gelden dezelfde voorwaarden als bij een KEW, zoals de bandbreedte en minimumlooptijd.`,tags:['sew','overgangsrecht','spaarrekening'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-137',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met een bankspaarhypotheek bij overstap naar een andere geldverstrekker?',antwoord:`Een bestaande spaarrekening eigen woning kan onder voorwaarden worden overgezet. Het overgangsrecht kan behouden blijven als aan de fiscale voorwaarden wordt voldaan. Controleer of de nieuwe geldverstrekker zo een rekening aanbiedt en leg de gevolgen vast.`,tags:['bankspaar','overstappen','overgangsrecht'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-138',thema:'fiscaal-eigen-woning',vraag:'Waarom moet bij overgangsrecht de stand per 31 december 2012 worden bewaard?',antwoord:`De stand van de eigenwoningschuld op die datum bepaalt het maximum dat onder het overgangsrecht valt. Bij latere wijzigingen moet je kunnen aantonen welk deel bestaande eigenwoningschuld is. Vraag een historisch overzicht op bij de geldverstrekker en neem dat op in het dossier.`,tags:['overgangsrecht','bewijs','dossier'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-139',thema:'fiscaal-eigen-woning',vraag:'Wat is een veelgemaakte fout bij de aflossingseis in een offerte?',antwoord:`Een veelgemaakte fout is een looptijd die langer is dan 360 maanden, terwijl het deel als eigenwoningschuld is gelabeld. Ook wordt soms een aflossingsvrij deel zonder overgangsrecht als box 1 behandeld. Controleer per leningdeel de looptijd, de aflossingsvorm en het fiscale label voordat de klant tekent.`,tags:['offerte','aflossingseis','fout'],bron:'Wet IB 2001'},
 {id:'fex-140',thema:'fiscaal-eigen-woning',vraag:'Hoe verhouden overgangsrecht en eigenwoningreserve zich tot elkaar?',antwoord:`De eigenwoningreserve bepaalt hoeveel eigenwoningschuld maximaal mogelijk is. Het overgangsrecht bepaalt welk deel daarvan zonder aflossingseis mag blijven. Bij verhuizing worden beide los berekend. Leg beide berekeningen afzonderlijk vast in het adviesrapport.`,tags:['overgangsrecht','eigenwoningreserve','verhuizing'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-141',thema:'fiscaal-eigen-woning',vraag:'Mag een overgangsrecht-lening tijdens de looptijd worden omgezet naar aflossingsvrij?',antwoord:`Een lening die onder overgangsrecht valt, mag aflossingsvrij blijven of worden. Het bedrag met overgangsrecht wordt niet hoger door de omzetting. Controleer wel de acceptatievoorwaarden en de maximale aflossingsvrije ruimte bij de geldverstrekker.`,tags:['overgangsrecht','aflossingsvrij','omzetten'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-142',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met het overgangsrecht bij een scheiding?',antwoord:`Bij een scheiding kan de partner die de woning overneemt het overgangsrecht van het overgenomen deel onder voorwaarden behouden. Voor het deel dat er extra bij wordt geleend, geldt de aflossingseis. Laat de fiscale gevolgen per partner vastleggen in het dossier en in het convenant.`,tags:['scheiding','overgangsrecht','overname'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-143',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met het overgangsrecht bij overlijden van een partner?',antwoord:`De langstlevende partner die de woning en de schuld verkrijgt, kan in principe de fiscale historie van de overleden partner overnemen. Dat geldt ook voor het overgangsrecht van die schuld. Laat dit toetsen en leg vast welke historie is overgenomen.`,tags:['overlijden','overgangsrecht','langstlevende'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-144',thema:'fiscaal-eigen-woning',vraag:'Hoe herken je overgangsrecht in een oude hypotheekakte?',antwoord:`De akte vermeldt vaak de datum van de lening en de leningdelen, maar niet altijd de fiscale status. Vergelijk de datum met 31 december 2012 en kijk naar latere wijzigingen. Vraag bij twijfel een fiscale historie op bij de geldverstrekker of de klant.`,tags:['hypotheekakte','overgangsrecht','historie'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-145',thema:'fiscaal-eigen-woning',vraag:'Geldt het overgangsrecht ook voor een lening van de eigen BV van voor 2013?',antwoord:`Ja, als die lening op 31 december 2012 eigenwoningschuld was. Voor die schuld geldt de aflossingseis dan niet. Voor wijzigingen na die datum gelden de gewone regels. Laat de leningovereenkomst en de rente zakelijk toetsen.`,tags:['eigen bv','overgangsrecht','2012'],bron:'Wet IB 2001 hfdst. 10bis'},
 {id:'fex-146',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigenwoningreserve bij een ruil van woningen?',antwoord:`Ook bij ruil wordt de oude woning vervreemd. De waarde van de weggegeven woning geldt als vervreemdingsprijs. Daarmee kan een eigenwoningreserve ontstaan. Laat de waarde en de verwerving door een notaris en taxateur vastleggen.`,tags:['ruil','vervreemding','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-147',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met een eigenwoningreserve die bijna vervalt?',antwoord:`Als de termijn van drie jaar bijna afloopt, verandert de maximale eigenwoningschuld bij aankoop kort daarna. Een aankoop na de vervaldatum valt buiten de reserve. Bespreek de timing en het risico van vertraging bij de levering. Leg de datum van vervallen en de gemaakte afspraken vast.`,tags:['vervaldatum','timing','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-148',thema:'fiscaal-eigen-woning',vraag:'Wat is het effect van een eigenwoningreserve op de leencapaciteit?',antwoord:`De eigenwoningreserve beperkt alleen de fiscale eigenwoningschuld, niet direct de leencapaciteit. Een lening boven de maximale eigenwoningschuld is box 3-schuld. Voor box 3-leningdelen kan de geldverstrekker een andere toetsing hanteren. Controleer de voorwaarden van de geldverstrekker.`,tags:['leencapaciteit','box 3','eigenwoningreserve'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'fex-149',thema:'fiscaal-eigen-woning',vraag:'Moet de eigenwoningreserve worden opgegeven in de aangifte?',antwoord:`De klant moet de gegevens van de verkoop en de eigenwoningreserve correct opnemen in de aangifte. Daarmee kan de Belastingdienst toetsen of de nieuwe eigenwoningschuld klopt. Bewaar de berekening, zodat de klant die bij een controle kan overleggen.`,tags:['aangifte','eigenwoningreserve','controle'],bron:'Belastingdienst'},
 {id:'fex-150',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de bijleenregeling als de oude woning aan een familielid wordt verkocht?',antwoord:`Ook dan is er een vervreemding en kan een eigenwoningreserve ontstaan. Bij een prijs onder de marktwaarde kunnen schenkbelasting en een andere vervreemdingsprijs een rol spelen. Laat de waarde onderbouwen met een taxatie. Laat de fiscale gevolgen toetsen en leg ze vast.`,tags:['familie','verkoop','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-151',thema:'fiscaal-eigen-woning',vraag:'Mogen fiscale partners de verdeling van de eigenwoningpost elk jaar anders kiezen?',antwoord:`Ja. Fiscale partners mogen het saldo van eigenwoningforfait en aftrekbare kosten elk jaar opnieuw verdelen. De verdeling mag in elke gewenste verhouding, ook helemaal bij één partner. Vaak is het gunstig de post toe te rekenen aan de partner met het hoogste tarief, maar dat hangt af van de hele aangifte.`,tags:['fiscale partners','verdeling','gemeenschappelijk'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-152',thema:'fiscaal-eigen-woning',vraag:'Maakt het voor fiscale partners uit wie eigenaar is van de woning?',antwoord:`Voor de renteaftrek maakt het tussen fiscale partners niet uit wie eigenaar en wie schuldenaar is. Het gaat om de eigen woning van de klant of zijn partner. De verdeling van de aftrek is vrij. Civielrechtelijk blijft de eigendom wel belangrijk, bijvoorbeeld bij scheiding of overlijden.`,tags:['fiscale partners','eigendom','renteaftrek'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-153',thema:'fiscaal-eigen-woning',vraag:'Wat is het fiscale gevolg van huwelijkse voorwaarden voor de eigen woning?',antwoord:`Bij huwelijkse voorwaarden kan de woning eigendom zijn van één partner. Fiscaal zijn de echtgenoten wel fiscale partners en kunnen ze de eigenwoningpost vrij verdelen. Bij scheiding of overlijden volgen de gevolgen de eigendom en de schuld. Leg de eigendomssituatie en eventuele vergoedingsrechten vast.`,tags:['huwelijkse voorwaarden','eigendom','partners'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-154',thema:'fiscaal-eigen-woning',vraag:'Kan iemand kiezen om het hele jaar fiscaal partner te zijn als het partnerschap halverwege begint?',antwoord:`Ja. Wie een deel van het jaar fiscaal partner is, kan onder voorwaarden kiezen om voor het hele jaar als fiscaal partner te gelden. Dan kan ook de eigenwoningpost over het hele jaar worden verdeeld. Beide partners moeten deze keuze maken in de aangifte.`,tags:['fiscaal partner','keuze','deel jaar'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-155',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de renteaftrek als samenwoners geen fiscale partners zijn en de woning 50-50 bezitten?',antwoord:`Ieder trekt de rente af over zijn eigen deel van de eigenwoningschuld. De schuld moet dan ook per persoon aan het eigen deel van de woning zijn besteed. Betaalt één partner meer dan zijn deel, dan kan er een vordering of schenking ontstaan. Leg de afspraken vast in een samenlevingscontract.`,tags:['samenwonen','50-50','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-156',thema:'fiscaal-eigen-woning',vraag:'Kan een niet-eigenaar die meeschuldenaar is rente aftrekken?',antwoord:`Een meeschuldenaar die geen eigenaar is en geen fiscaal partner van de eigenaar, heeft geen eigen woning. Hij kan de rente daarom niet aftrekken. Wordt hij later fiscaal partner, dan verandert dit. Leg uit dat hoofdelijke aansprakelijkheid iets anders is dan fiscale aftrek.`,tags:['meeschuldenaar','eigendom','samenwonen'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-157',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als samenwoners scheef eigendom en scheve schuld hebben?',antwoord:`Bij niet-fiscale partners is per persoon alleen de rente aftrekbaar over de eigen schuld die aan het eigen deel is besteed. Scheve verhoudingen leiden snel tot niet-aftrekbare rente of verkapte schenkingen. Stem eigendom, schuld en betalingen op elkaar af. Leg de verhouding vast in akte en dossier.`,tags:['samenwonen','scheef eigendom','schenking'],bron:'Belastingdienst'},
 {id:'fex-158',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigenwoningschuld als samenwoners later trouwen?',antwoord:`Na het huwelijk worden ze fiscale partners en mogen ze de eigenwoningpost vrij verdelen. De bestaande schuld en eigendomsverhouding blijven civielrechtelijk gelijk, tenzij er iets wordt gewijzigd. De fiscale historie per leningdeel blijft bestaan. Controleer of de huwelijksvorm gevolgen heeft voor de eigendom.`,tags:['trouwen','fiscale partners','historie'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-159',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de renteaftrek als broers of zussen samen een woning kopen?',antwoord:`Broers en zussen zijn geen fiscale partners. Ieder heeft alleen een eigen woning als de woning zijn eigen hoofdverblijf is. Ieder trekt de rente af over zijn eigen eigenwoningschuld voor zijn eigen deel. Leg eigendom, schuld en betalingen per persoon vast.`,tags:['broers','zussen','medeeigendom'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-160',thema:'fiscaal-eigen-woning',vraag:'Kunnen ouders als meeschuldenaar bijdragen aan de renteaftrek van het kind?',antwoord:`Nee. Ouders die alleen meeschuldenaar zijn, hebben geen eigen woning bij die woning. Zij kunnen de rente niet aftrekken. Het kind kan de rente aftrekken die het zelf betaalt over de eigenwoningschuld. Betalen de ouders, dan is dat mogelijk een schenking.`,tags:['ouders','meeschuldenaar','schenking'],bron:'Belastingdienst'},
 {id:'fex-161',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er fiscaal met de vertrokken partner die na scheiding een nieuwe woning koopt?',antwoord:`Een persoon kan in beginsel maar één eigen woning hebben. Koopt de vertrokken partner een nieuwe woning, dan kan dat gevolgen hebben voor de aftrek op de oude woning. Laat per situatie toetsen welke woning als eigen woning geldt en tot wanneer. Leg de uitkomst vast.`,tags:['scheiding','nieuwe woning','eigen woning'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-162',thema:'fiscaal-eigen-woning',vraag:'Is de rente die een ex-partner betaalt voor de woning van de ander aftrekbaar als alimentatie?',antwoord:`Betaalt een ex-partner woonlasten als onderdeel van partneralimentatie, dan kan dat als persoonsgebonden aftrek gelden. Dat is een andere regeling dan de renteaftrek eigen woning. Voor kinderalimentatie geldt dit niet. Leg de afspraken duidelijk vast in het convenant en laat ze fiscaal toetsen.`,tags:['alimentatie','scheiding','persoonsgebonden aftrek'],bron:'Wet IB 2001'},
 {id:'fex-163',thema:'fiscaal-eigen-woning',vraag:'Is overdrachtsbelasting verschuldigd bij overname van de woning bij scheiding?',antwoord:`Bij verdeling van een huwelijksgemeenschap of tussen geregistreerde partners geldt in de regel een vrijstelling. Voor ongehuwd samenwonenden geldt dat alleen onder bepaalde voorwaarden. Laat de notaris dit vooraf beoordelen en neem de uitkomst op in de kostenopstelling.`,tags:['overdrachtsbelasting','scheiding','vrijstelling'],bron:'Wet op belastingen van rechtsverkeer'},
 {id:'fex-164',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt bij scheiding de lening voor het uitkopen van de ex-partner behandeld?',antwoord:`De lening om het aandeel van de ex-partner te kopen, is een lening voor verwerving van de eigen woning. Die kan eigenwoningschuld zijn als aan de aflossingseis wordt voldaan, behoudens overgenomen fiscale historie. Houd rekening met de eigenwoningreserve die bij de vertrekkende partner ontstaat.`,tags:['uitkoop','scheiding','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-165',thema:'fiscaal-eigen-woning',vraag:'Ontstaat er bij de vertrekkende partner een eigenwoningreserve?',antwoord:`Ja, dat kan. De vertrekkende partner vervreemdt zijn aandeel in de woning. Is zijn deel van de verkoopprijs hoger dan zijn deel van de eigenwoningschuld, dan ontstaat een eigenwoningreserve. Die speelt mee als hij binnen drie jaar een nieuwe woning koopt.`,tags:['scheiding','eigenwoningreserve','vertrekkende partner'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-166',thema:'fiscaal-eigen-woning',vraag:'Wat moet je vastleggen bij een scheiding met een eigen woning?',antwoord:`Leg vast wie de woning overneemt, tegen welke waarde en welke leningdelen worden overgenomen of afgelost. Noteer per partner de fiscale historie, het overgangsrecht en een eventuele eigenwoningreserve. Vermeld ook de datum van vertrek in verband met de fiscale termijnen. Stem af met notaris en mediator.`,tags:['scheiding','vastlegging','dossier'],bron:'Belastingdienst'},
 {id:'fex-167',thema:'fiscaal-eigen-woning',vraag:'Hoe lang blijft een ex-partner hoofdelijk aansprakelijk voor de hypotheek?',antwoord:`Hoofdelijke aansprakelijkheid eindigt pas als de geldverstrekker de ex-partner ontslaat. Dat staat los van de fiscale situatie. Zonder ontslag blijft de ex-partner aansprakelijk, ook als hij geen renteaftrek meer heeft. Controleer de voorwaarden van de geldverstrekker voor ontslag uit hoofdelijkheid.`,tags:['hoofdelijkheid','scheiding','ontslag'],bron:'Burgerlijk Wetboek'},
 {id:'fex-168',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning in het jaar van overlijden van een partner?',antwoord:`In het jaar van overlijden kan de eigenwoningpost nog tussen de partners worden verdeeld. Na het overlijden heeft de langstlevende partner de woning en de schuld. De aangifte van de overledene wordt door de erfgenamen ingediend. Leg vast welke verdeling is gekozen.`,tags:['overlijden','aangifte','verdeling'],bron:'Belastingdienst'},
 {id:'fex-169',thema:'fiscaal-eigen-woning',vraag:'Gaat de fiscale historie van de schuld over op de langstlevende partner?',antwoord:`Ja, in principe kan de langstlevende partner die de woning en schuld verkrijgt, de fiscale historie overnemen. Denk aan overgangsrecht, resterende looptijd en aflossingsschema. Laat dit toetsen bij een ingewikkelde nalatenschap en leg vast welke historie geldt.`,tags:['langstlevende','fiscale historie','overlijden'],bron:'Belastingdienst'},
 {id:'fex-170',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de woning als de overledene alleenstaand was?',antwoord:`De woning gaat naar de erfgenamen. Voor hen is het geen eigen woning, tenzij een erfgenaam er zelf gaat wonen. De woning en de schuld vallen dan bij de erfgenamen in box 3. Bespreek tijdig de verkoop of financiering met de erfgenamen.`,tags:['erfgenamen','box 3','overlijden'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-171',thema:'fiscaal-eigen-woning',vraag:'Kan een erfgenaam die in de geërfde woning gaat wonen rente aftrekken?',antwoord:`Een lening om andere erfgenamen uit te kopen, is een verwerving en kan eigenwoningschuld zijn. Of een overgenomen schuld van de overledene eigenwoningschuld is, hangt af van de situatie. Laat dit fiscaal toetsen voordat de verdeling wordt vastgelegd.`,tags:['erfgenaam','uitkopen','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-172',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt een uitkering van een overlijdensrisicoverzekering belast?',antwoord:`Een uitkering uit een overlijdensrisicoverzekering kan onder de erfbelasting vallen. Dat hangt af van wie verzekeringnemer is en wie de premie betaalt. Bij een kruislingse constructie tussen partners kan dit soms worden voorkomen. Controleer de polis en leg de fiscale gevolgen vast.`,tags:['orv','erfbelasting','kruislings'],bron:'Successiewet 1956'},
 {id:'fex-173',thema:'fiscaal-eigen-woning',vraag:'Wat betekent een aflossing met een ORV-uitkering voor de fiscale positie?',antwoord:`Een aflossing verlaagt de eigenwoningschuld en daarmee de aftrekbare rente. Bij een lage restschuld kan de Wet Hillen een rol spelen. Bij overgangsrecht vervalt dat voor het afgeloste deel definitief. Bespreek dit voordat de langstlevende besluit tot volledige aflossing.`,tags:['orv','aflossing','langstlevende'],bron:'Belastingdienst'},
 {id:'fex-174',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning als de langstlevende partner hertrouwt?',antwoord:`De woning blijft een eigen woning zolang de langstlevende er woont. Met een nieuwe partner gelden de gewone regels voor fiscaal partnerschap en verdeling. Een testament kan civielrechtelijke gevolgen hebben voor de kinderen. Adviseer om notariële vastlegging bij gezinsvorming te laten controleren.`,tags:['hertrouwen','langstlevende','testament'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-175',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de wettelijke verdeling voor de eigen woning?',antwoord:`Bij de wettelijke verdeling krijgt de langstlevende partner de goederen, waaronder de woning, en de schulden. De kinderen krijgen een vordering op de langstlevende. Fiscaal is de woning daarmee de eigen woning van de langstlevende. Laat de vorderingen en de gevolgen voor de erfbelasting door de notaris toelichten.`,tags:['wettelijke verdeling','langstlevende','kinderen'],bron:'Burgerlijk Wetboek'},
 {id:'fex-176',thema:'fiscaal-eigen-woning',vraag:'Is rente over een onderbedelingsschuld aan kinderen aftrekbaar als eigenwoningrente?',antwoord:`In de regel niet. Een schuld aan kinderen uit de wettelijke verdeling is geen lening voor verwerving of verbetering van de woning. De rente daarover is daarom geen eigenwoningrente. Laat de fiscale behandeling per situatie toetsen.`,tags:['onderbedeling','kinderen','renteaftrek'],bron:'Belastingdienst'},
 {id:'fex-177',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er als een geregistreerd partner de woning erft?',antwoord:`Een geregistreerd partner wordt fiscaal hetzelfde behandeld als een echtgenoot. Bij overlijden kan de partner de woning en de schuld met de fiscale historie overnemen. Ook bij de erfbelasting geldt de partnervrijstelling. Zie de Belastingdienst voor het actuele vrijstellingsbedrag.`,tags:['geregistreerd partner','erven','partnervrijstelling'],bron:'Successiewet 1956'},
 {id:'fex-178',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er fiscaal als de langstlevende partner de woning na overlijden verkoopt?',antwoord:`De verkoop is een vervreemding door de langstlevende. Er kan dan een eigenwoningreserve ontstaan als de opbrengst hoger is dan de eigenwoningschuld. Koopt de langstlevende binnen drie jaar een nieuwe woning, dan speelt die reserve mee. Leg de berekening vast.`,tags:['langstlevende','verkoop','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-179',thema:'fiscaal-eigen-woning',vraag:'Kan een verblijvingsbeding gevolgen hebben voor de eigen woning?',antwoord:`Met een verblijvingsbeding kan het aandeel van de overledene naar de langstlevende gaan. Dat kan erfbelasting of overdrachtsbelasting met zich meebrengen. Fiscaal wordt de woning dan voor het geheel de eigen woning van de langstlevende. Laat de notaris de gevolgen beoordelen.`,tags:['verblijvingsbeding','samenwoners','notaris'],bron:'Burgerlijk Wetboek'},
 {id:'fex-180',thema:'fiscaal-eigen-woning',vraag:'Kan een familielening later worden overgesloten naar een bank?',antwoord:`Ja. Een familielening die eigenwoningschuld is, kan worden afgelost met een nieuwe lening van een bank. De nieuwe lening neemt de fiscale historie over voor zover die de oude eigenwoningschuld vervangt. De resterende looptijd en het schema lopen door. Leg de historie van de familielening vast.`,tags:['familielening','oversluiten','historie'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-181',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de familielening als het kind de woning verkoopt?',antwoord:`Bij verkoop moet de familielening vaak worden afgelost. Dat volgt uit de leningovereenkomst. Wordt de lening niet afgelost en niet aan een nieuwe woning besteed, dan is het geen eigenwoningschuld meer. Neem de familielening mee in de berekening van de eigenwoningreserve.`,tags:['familielening','verkoop','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-182',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als het kind de familielening niet volgens schema aflost?',antwoord:`Dan kan een aflossingsachterstand ontstaan. Wordt die niet tijdig ingehaald, dan kan de lening voor dat deel geen eigenwoningschuld meer zijn. Bij familie wordt dit snel informeel opgelost. Wijs beide partijen op het belang van aantoonbare betalingen volgens schema.`,tags:['familielening','achterstand','aflossingseis'],bron:'Wet IB 2001'},
 {id:'fex-183',thema:'fiscaal-eigen-woning',vraag:'Kunnen ouders jaarlijks rente of aflossing schenken bij een familielening?',antwoord:`Ouders kunnen bedragen schenken, binnen of boven de vrijstelling. Een schenking die wordt verrekend met verschuldigde rente, betekent dat de rente niet echt is betaald. Dat kan de aftrek in gevaar brengen. Adviseer betalingen en schenkingen gescheiden en aantoonbaar via de bank te laten lopen.`,tags:['schenking','rente','familielening'],bron:'Successiewet 1956'},
 {id:'fex-184',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een kind met een familielening gaat samenwonen?',antwoord:`De schuld blijft van het kind. Wordt de partner mede-eigenaar of fiscaal partner, dan verandert de fiscale verdeling. Een nieuwe partner wordt niet automatisch schuldenaar bij de ouders. Leg vast hoe eigendom en schuld na het samenwonen zijn verdeeld.`,tags:['samenwonen','familielening','eigendom'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-185',thema:'fiscaal-eigen-woning',vraag:'Is de eigen woning van een minderjarige mogelijk?',antwoord:`Een minderjarige kan eigenaar zijn van een woning, bijvoorbeeld na een erfenis. Voor het aangaan van een hypotheek is wel toestemming nodig. Is de woning niet het hoofdverblijf van de minderjarige, dan valt deze in box 3. In de praktijk is dit zeldzaam en vraagt het notarieel en juridisch advies.`,tags:['minderjarige','eigendom','erfenis'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-186',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt de verdeling als een van de partners geen inkomen heeft?',antwoord:`Bij fiscale partners mag de eigenwoningpost volledig aan de partner met inkomen worden toegerekend. Dat geeft vaak het grootste fiscale voordeel. Houd ook rekening met heffingskortingen van de partner zonder inkomen. Laat de verdeling in de aangifte optimaliseren.`,tags:['verdeling','partner zonder inkomen','aangifte'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-187',thema:'fiscaal-eigen-woning',vraag:'Kan een fiscale partner die niet in de woning woont de rente aftrekken?',antwoord:`Fiscale partners wonen meestal samen, maar niet altijd. Bijvoorbeeld bij gehuwden die gescheiden leven en nog fiscaal partner zijn. Dan moet per situatie worden bekeken of de woning een eigen woning is. Laat dit fiscaal toetsen.`,tags:['fiscale partner','gescheiden leven','eigen woning'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-188',thema:'fiscaal-eigen-woning',vraag:'Wanneer eindigt het fiscale partnerschap bij een scheiding?',antwoord:`Bij gehuwden eindigt het partnerschap meestal als ze niet meer op hetzelfde adres staan ingeschreven en een verzoek tot echtscheiding is ingediend. Daarna gelden de regels voor de ex-partner. Noteer de datum van uitschrijving en indiening van het verzoek in het dossier.`,tags:['fiscaal partner','scheiding','einddatum'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-189',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met de aangifte in het jaar van scheiding?',antwoord:`In het jaar van scheiding is er vaak een deel van het jaar fiscaal partnerschap. Voor die periode kan de eigenwoningpost worden verdeeld en mogelijk kan voor het hele jaar worden gekozen. Daarna volgt per persoon de eigen situatie. Laat de aangifte door een fiscalist afstemmen met het convenant.`,tags:['scheiding','aangifte','partnerschap'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-190',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning als een partner tijdelijk elders gaat wonen bij relatieproblemen?',antwoord:`Gaat een partner tijdelijk elders wonen, dan blijft de woning zijn eigen woning zolang de tijdelijkheid duidelijk is. Bij een definitieve breuk gelden de regels voor scheiding. Noteer de data van vertrek en de afspraken. Dit voorkomt discussie over termijnen.`,tags:['tijdelijk elders','relatie','scheiding'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-191',thema:'fiscaal-eigen-woning',vraag:'Kan een schenking van ouders voor aflossing de fiscale historie veranderen?',antwoord:`Een schenking zelf verandert de historie niet. Wordt de schenking gebruikt voor aflossing, dan vermindert de eigenwoningschuld. Bij overgangsrecht vervalt dat deel definitief. Neem de schenking op in het overzicht van leningdelen.`,tags:['schenking','aflossing','historie'],bron:'Belastingdienst'},
 {id:'fex-192',thema:'fiscaal-eigen-woning',vraag:'Wat zijn de gevolgen als een kind de woning van de ouders koopt?',antwoord:`Voor het kind is het een verwerving van de eigen woning. Een lening daarvoor kan eigenwoningschuld zijn met aflossingseis. Bij een prijs onder de waarde kan een schenking ontstaan. Laat de waarde vaststellen met een taxatie en leg vast hoe de prijs is bepaald.`,tags:['ouders','koop','schenking'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-193',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er bij een koop van ouders met een lening van dezelfde ouders?',antwoord:`Dan zijn er twee stappen: de koop en de familielening. De lening kan eigenwoningschuld zijn als aan alle voorwaarden wordt voldaan. Voor de ouders ontstaat een vordering in box 3. Leg beide overeenkomsten afzonderlijk en zakelijk vast.`,tags:['ouders','familielening','koop'],bron:'Belastingdienst'},
 {id:'fex-194',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er bij een woning met een inwonende ouder?',antwoord:`Woont een ouder in bij het kind, dan blijft de woning de eigen woning van de eigenaar. Betaalt de ouder een vergoeding, dan kan dat als verhuur gelden en kan de kamerverhuurvrijstelling van belang zijn. Leg vast of er een vergoeding is en hoe hoog die is.`,tags:['inwonende ouder','mantelzorg','kamerverhuur'],bron:'Belastingdienst'},
 {id:'fex-195',thema:'fiscaal-eigen-woning',vraag:'Is een mantelzorgwoning op het eigen perceel een eigen woning?',antwoord:`Een mantelzorgwoning bij de woning kan een aanhorigheid zijn als die bij de woning hoort. Woont er een ander dan de eigenaar, dan kan het fiscale gevolgen hebben. Laat toetsen of de mantelzorgwoning onder de eigenwoningregeling valt.`,tags:['mantelzorgwoning','aanhorigheid','perceel'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-196',thema:'fiscaal-eigen-woning',vraag:'Wat zijn de fiscale gevolgen als een partner in een zorginstelling wordt opgenomen?',antwoord:`Blijft de andere partner in de woning, dan blijft het een eigen woning. Het fiscale partnerschap kan onder voorwaarden blijven bestaan. Laat de fiscale gevolgen toetsen bij langdurige opname en noteer de datum van opname in het dossier.`,tags:['zorginstelling','partner','eigen woning'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-197',thema:'fiscaal-eigen-woning',vraag:'Kan een woning in een BV toch eigen woning worden na overdracht naar privé?',antwoord:`Ja. Na overdracht naar privé kan de woning een eigen woning worden als die het hoofdverblijf is. Een lening om de woning van de BV te kopen kan eigenwoningschuld zijn met aflossingseis. Let op de fiscale gevolgen in de BV en op overdrachtsbelasting. Laat de overdracht door een fiscalist begeleiden.`,tags:['bv','overdracht','privé'],bron:'Belastingdienst'},
 {id:'fex-198',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er als een ondernemer de woning uit het ondernemingsvermogen haalt?',antwoord:`Bij overbrenging van de woning naar privé kan winst worden belast. Vanaf dan kan de woning een eigen woning zijn. Een lening die in de onderneming zat, gaat dan niet automatisch mee als eigenwoningschuld. Laat de gevolgen beoordelen door de fiscalist van de ondernemer.`,tags:['ondernemer','privé','overbrenging'],bron:'Belastingdienst'},
 {id:'fex-199',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met partners die beiden een eigenwoningreserve hebben?',antwoord:`Elke partner heeft dan een eigen reserve uit een eerdere verkoop. Bij samen kopen moet per persoon worden bekeken hoeveel eigenwoningschuld mogelijk is. Leg per partner de reserve, de vervaldatum en het eigendomsaandeel vast.`,tags:['partners','eigenwoningreserve','samen kopen'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-200',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er als de woning op naam van één samenwoner staat en de ander meebetaalt?',antwoord:`Zonder fiscaal partnerschap heeft alleen de eigenaar een eigen woning en alleen hij kan de rente aftrekken. De meebetalende partner heeft geen aftrek. Zijn bijdrage kan civielrechtelijk een lening, huur of schenking zijn. Leg de afspraken vast en verwijs naar de notaris voor een samenlevingscontract.`,tags:['samenwonen','meebetalen','eigendom'],bron:'Wet IB 2001 art. 3.111'},
 {id:'fex-201',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt een restschuld na verkoop vanaf 2018 fiscaal behandeld?',antwoord:`Een restschuld uit een verkoop vanaf 1 januari 2018 valt niet onder de restschuldregeling. De schuld hoort dan in box 3 en de rente is niet aftrekbaar. De schuld kan wel meetellen als schuld in box 3. Maak dit duidelijk in het advies over verkoop met verlies.`,tags:['restschuld','2018','box 3'],bron:'Wet IB 2001'},
 {id:'fex-202',thema:'fiscaal-eigen-woning',vraag:'Wat is een rekenvoorbeeld van een restschuld?',antwoord:`Stel dat de woning wordt verkocht voor € 280.000 met € 6.000 verkoopkosten, en de eigenwoningschuld is € 300.000. De restschuld is dan € 26.000. Bij verkoop binnen de periode van de restschuldregeling kan de rente onder voorwaarden aftrekbaar zijn. Bij verkoop daarna valt de restschuld in box 3. Het gaat om fictieve bedragen.`,tags:['rekenvoorbeeld','restschuld','verkoopkosten'],bron:'Wet IB 2001'},
 {id:'fex-203',thema:'fiscaal-eigen-woning',vraag:'Hoe lang is rente over een restschuld onder de restschuldregeling aftrekbaar?',antwoord:`Voor een restschuld uit een verkoop van 29 oktober 2012 tot en met 31 december 2017 is de rente maximaal 15 jaar aftrekbaar. Daarna valt de schuld in box 3. Noteer de einddatum in het dossier en bespreek tijdig aflossen of herfinancieren.`,tags:['restschuldregeling','15 jaar','einddatum'],bron:'Wet IB 2001'},
 {id:'fex-204',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er als een klant de hypotheek wil aflossen met een erfenis?',antwoord:`Een aflossing verlaagt de rente, maar ook de renteaftrek. Bij overgangsrecht vervalt dat voor het afgeloste deel definitief. Bij een lage restschuld kan de Wet Hillen meespelen. Bespreek ook de behoefte aan vrij beschikbaar vermogen en leg de afweging vast.`,tags:['erfenis','aflossing','afweging'],bron:'Belastingdienst'},
 {id:'fex-205',thema:'fiscaal-eigen-woning',vraag:'Telt een restschuld mee in de leencapaciteit voor een nieuwe woning?',antwoord:`Een restschuld is een schuld met maandlasten en telt in principe mee bij de beoordeling van de leencapaciteit. Hoe de geldverstrekker dit verwerkt, verschilt. Controleer de voorwaarden van de geldverstrekker en leg de verwerking vast.`,tags:['restschuld','leencapaciteit','acceptatie'],bron:'Gedragscode Hypothecaire Financieringen'},
 {id:'fex-206',thema:'fiscaal-eigen-woning',vraag:'Blijft de rente over een restschuld onder de regeling aftrekbaar als de klant gaat huren?',antwoord:`Ja. De restschuldregeling vereist geen nieuwe eigen woning. De rente blijft aftrekbaar zolang aan de voorwaarden wordt voldaan en de termijn van 15 jaar niet is verstreken. Noteer de einddatum en bespreek tijdig aflossen.`,tags:['restschuld','huren','renteaftrek'],bron:'Wet IB 2001'},
 {id:'fex-207',thema:'fiscaal-eigen-woning',vraag:'Wat is het verschil tussen een restschuld en een box 3-hypotheekdeel?',antwoord:`Een restschuld ontstaat na verkoop van de woning als de opbrengst te laag is. Een box 3-hypotheekdeel is een deel van een lopende hypotheek dat niet aan de eigen woning is besteed. Beide vallen meestal in box 3, behalve een restschuld onder de restschuldregeling. Verwar ze niet in de administratie.`,tags:['restschuld','box 3','onderscheid'],bron:'Belastingdienst'},
 {id:'fex-208',thema:'fiscaal-eigen-woning',vraag:'Moet een restschuld onder de regeling worden afgelost volgens een schema?',antwoord:`Een restschuld onder de regeling hoeft niet aan dezelfde aflossingseis te voldoen als een gewone eigenwoningschuld. Wel loopt de aftrek na 15 jaar af. Adviseer om de restschuld binnen die periode af te lossen. Controleer de voorwaarden van de geldverstrekker voor de restschuldfinanciering.`,tags:['restschuld','aflossing','schema'],bron:'Wet IB 2001'},
 {id:'fex-209',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de restschuld als de klant later een nieuwe woning koopt?',antwoord:`De restschuld blijft een aparte schuld. Die wordt niet opgeteld bij de nieuwe eigenwoningschuld. Er is ook geen eigenwoningreserve, want de reserve kan niet negatief zijn. Houd de restschuld als apart onderdeel bij in het dossier.`,tags:['restschuld','nieuwe woning','eigenwoningreserve'],bron:'Wet IB 2001'},
 {id:'fex-210',thema:'fiscaal-eigen-woning',vraag:'Hoe werken box 3-schulden in het algemeen?',antwoord:`Schulden in box 3 verminderen de grondslag van sparen en beleggen. Er geldt een drempel waaronder schulden niet meetellen. De waardering gebeurt op 1 januari. Zie de Belastingdienst voor de actuele drempel en het rendementspercentage.`,tags:['box 3','schulden','drempel'],bron:'Wet IB 2001 hfdst. 5'},
 {id:'fex-211',thema:'fiscaal-eigen-woning',vraag:'Is een studieschuld een box 3-schuld?',antwoord:`Ja. Een studieschuld bij DUO is een schuld die in box 3 meetelt. De rente is niet aftrekbaar in box 1. Voor de hypotheek is de studieschuld wel van belang voor de leencapaciteit. Volg daarvoor de actuele normen en de voorwaarden van de geldverstrekker.`,tags:['studieschuld','duo','box 3'],bron:'Wet IB 2001 hfdst. 5'},
 {id:'fex-212',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt een hypotheek op een verhuurde woning fiscaal behandeld?',antwoord:`Een verhuurde woning is geen eigen woning en valt in box 3. De schuld die daarvoor is aangegaan, telt ook in box 3. De rente is niet aftrekbaar in box 1. Voor de waardering van verhuurde woningen gelden aparte regels; zie de Belastingdienst voor de actuele regeling.`,tags:['verhuur','box 3','beleggingspand'],bron:'Wet IB 2001 hfdst. 5'},
 {id:'fex-213',thema:'fiscaal-eigen-woning',vraag:'Wat is het fiscale verschil tussen vakantieverhuur en structurele verhuur van de eigen woning?',antwoord:`Bij tijdelijke verhuur, zoals tijdens de vakantie, blijft de woning eigen woning en wordt een deel van de huur in box 1 belast. Bij structurele verhuur is de woning geen eigen woning meer en valt deze met de schuld in box 3. De grens hangt af van de feiten. Leg de verhuurafspraken vast.`,tags:['verhuur','vakantie','structureel'],bron:'Belastingdienst'},
 {id:'fex-214',thema:'fiscaal-eigen-woning',vraag:'Mogen fiscale partners box 3-schulden onderling verdelen?',antwoord:`Fiscale partners mogen de gezamenlijke grondslag in box 3 vrij verdelen. Daarmee kan ook het effect van schulden worden verdeeld. Leg de keuze vast in de aangifte. Laat de optimale verdeling door een fiscalist of aangifteprogramma berekenen.`,tags:['box 3','partners','verdeling'],bron:'Wet IB 2001 hfdst. 5'},
 {id:'fex-215',thema:'fiscaal-eigen-woning',vraag:'Telt een box 3-hypotheekdeel mee op de peildatum?',antwoord:`Ja. In box 3 telt de stand van de schuld op de peildatum, 1 januari. Een aflossing net voor die datum kan dus effect hebben op de berekening. Bespreek dit niet als belastingadvies, maar wijs de klant op de werking. Leg vast dat de klant hierover is geïnformeerd.`,tags:['peildatum','box 3','aflossing'],bron:'Wet IB 2001 hfdst. 5'},
 {id:'fex-216',thema:'fiscaal-eigen-woning',vraag:'Kan een box 3-schuld later omgezet worden in eigenwoningschuld?',antwoord:`Een box 3-schuld wordt niet zomaar eigenwoningschuld. Alleen als nieuw geleend geld aan de eigen woning wordt besteed, kan een nieuwe eigenwoningschuld ontstaan. Een eerdere box 3-besteding blijft box 3. Leg de besteding bij elke wijziging vast.`,tags:['box 3','omzetten','eigenwoningschuld'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-217',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant de oude woning verhuurt in plaats van verkoopt?',antwoord:`De woning valt vanaf de verhuur in box 3, net als de schuld die erbij hoort. Het kan gevolgen hebben voor overgangsrecht en eigenwoningreserve. Controleer of de geldverstrekker verhuur toestaat. Leg de fiscale en contractuele gevolgen vast voordat de klant beslist.`,tags:['verhuur','oude woning','box 3'],bron:'Belastingdienst'},
 {id:'fex-218',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er bij verhuur aan een kind?',antwoord:`Een woning die aan een kind wordt verhuurd, is voor de ouder geen eigen woning. De woning en de schuld vallen in box 3. Bij een lage huur kan een schenking ontstaan. Leg de huurprijs en de afspraken vast.`,tags:['verhuur','kind','box 3'],bron:'Belastingdienst'},
 {id:'fex-219',thema:'fiscaal-eigen-woning',vraag:'Geldt voor een buy-to-let-financiering de eigenwoningregeling?',antwoord:`Nee. Bij een financiering voor een verhuurde woning is er geen eigen woning. De rente is niet aftrekbaar in box 1 en de aflossingseis is niet van toepassing. De geldverstrekker heeft eigen acceptatievoorwaarden voor verhuurde woningen. Controleer die voorwaarden.`,tags:['buy-to-let','verhuur','box 3'],bron:'Belastingdienst'},
 {id:'fex-220',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een eigen woning wordt omgezet in een verhuurde woning met behoud van de hypotheek?',antwoord:`De lening blijft bestaan maar is vanaf de verhuur geen eigenwoningschuld meer. Komt de klant later weer in de woning wonen, dan wordt opnieuw beoordeeld wat eigenwoningschuld kan zijn. Fiscale historie en overgangsrecht kunnen dan verloren zijn. Laat dit vooraf toetsen.`,tags:['verhuur','status','terugkeer'],bron:'Belastingdienst'},
 {id:'fex-221',thema:'fiscaal-eigen-woning',vraag:'Wat moet in het dossier staan over de fiscale status van de lening?',antwoord:`Leg per leningdeel vast of het eigenwoningschuld, box 3-schuld of restschuld is. Noteer startdatum, looptijd, aflossingsvorm en eventueel overgangsrecht. Voeg de berekening van de eigenwoningreserve toe. Dit maakt het advies controleerbaar en helpt bij latere wijzigingen.`,tags:['dossier','leningdelen','fiscale status'],bron:'Wft'},
 {id:'fex-222',thema:'fiscaal-eigen-woning',vraag:'Hoe documenteer je de besteding van een verbouwingslening?',antwoord:`Bewaar offertes, facturen en betalingsbewijzen van de verbouwing. Koppel ze aan het bedrag van het bouwdepot of de lening. Zo kan de klant bij een controle aantonen dat het geld aan de woning is besteed. Leg in het dossier vast dat de klant deze stukken moet bewaren.`,tags:['verbouwing','facturen','bewijs'],bron:'Belastingdienst'},
 {id:'fex-223',thema:'fiscaal-eigen-woning',vraag:'Hoe lang moet een klant stukken over de eigen woning bewaren?',antwoord:`De fiscale gevolgen van een lening kunnen tientallen jaren doorlopen. Stukken over aankoop, verkoop, leningdelen en eigenwoningreserve zijn daarom lang relevant. De Belastingdienst kan in de regel tot vijf jaar na het belastingjaar navorderen. Adviseer de klant de stukken te bewaren zolang de lening of de fiscale historie loopt.`,tags:['bewaren','navordering','stukken'],bron:'Algemene wet inzake rijksbelastingen'},
 {id:'fex-224',thema:'fiscaal-eigen-woning',vraag:'Mag een hypotheekadviseur fiscaal advies geven?',antwoord:`Een hypotheekadviseur moet de fiscale gevolgen van zijn advies goed uitleggen. Voor complexe fiscale vragen, zoals internationale situaties of ondernemers, is een fiscalist nodig. Leg vast welke fiscale aspecten zijn besproken en waar naar een specialist is verwezen.`,tags:['zorgplicht','fiscalist','grenzen'],bron:'Wft'},
 {id:'fex-225',thema:'fiscaal-eigen-woning',vraag:'Welke fiscale uitgangspunten moeten in het adviesrapport staan?',antwoord:`Vermeld welk aftrektarief, welk eigenwoningforfait en welke fiscale status per leningdeel zijn gebruikt. Geef aan dat deze uitgangspunten kunnen veranderen. Noem ook de einddatum van de renteaftrek per deel. Zo begrijpt de klant waarop de netto last is gebaseerd.`,tags:['adviesrapport','uitgangspunten','netto last'],bron:'Wft'},
 {id:'fex-226',thema:'fiscaal-eigen-woning',vraag:'Hoe benoem je in het advies dat fiscale regels kunnen veranderen?',antwoord:`Leg uit dat de netto last afhangt van fiscale regels die de overheid kan wijzigen. Gebruik in de berekening de actuele regels en noem de datum waarop ze zijn bepaald. Vermeld dat toekomstige wijzigingen de netto last kunnen verhogen. Laat de klant dit bevestigen.`,tags:['fiscale wijzigingen','risico','adviesrapport'],bron:'Wft'},
 {id:'fex-227',thema:'fiscaal-eigen-woning',vraag:'Wat zijn veelgemaakte fouten bij advies over de eigen woning?',antwoord:`Veelvoorkomende fouten zijn het vergeten van de eigenwoningreserve, het onjuist toepassen van overgangsrecht en het niet splitsen van consumptieve bestedingen. Ook de dertigjaarstermijn van oude leningdelen wordt vaak gemist. Werk met een vaste checklist en laat een tweede adviseur meekijken bij complexe dossiers.`,tags:['fouten','checklist','kwaliteit'],bron:'Wft'},
 {id:'fex-228',thema:'fiscaal-eigen-woning',vraag:'Hoe controleer je de fiscale status bij een klant die van een andere adviseur komt?',antwoord:`Vraag het vorige adviesrapport, de hypotheekakte en een overzicht van de leningdelen op. Controleer startdata, overgangsrecht en eventuele eigenwoningreserves. Neem niets over zonder eigen controle. Leg vast welke stukken zijn ontvangen en welke informatie ontbreekt.`,tags:['overdracht','controle','nieuwe klant'],bron:'Wft'},
 {id:'fex-229',thema:'fiscaal-eigen-woning',vraag:'Wat is het risico van het niet tijdig signaleren van het einde van de renteaftrek?',antwoord:`Na afloop van de termijn stijgt de netto last, soms flink. Klanten worden daardoor verrast en kunnen in betalingsproblemen komen. Plan een signalering in het klantbeheer voor leningdelen met een einddatum binnen enkele jaren. Leg vast wanneer de klant is geïnformeerd.`,tags:['einde aftrek','signalering','klantbeheer'],bron:'Wft'},
 {id:'fex-230',thema:'fiscaal-eigen-woning',vraag:'Moet de adviseur de klant wijzen op wijziging van de voorlopige aanslag?',antwoord:`Het is goed vakmanschap om de klant te wijzen op de voorlopige aanslag na aankoop, oversluiten of renteherziening. Een te hoge teruggave leidt later tot terugbetaling. Leg vast dat de klant hierop is gewezen. De klant blijft zelf verantwoordelijk voor de aanvraag.`,tags:['voorlopige aanslag','informatie','klant'],bron:'Belastingdienst'},
 {id:'fex-231',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met een klant die een deel van de hypotheek voor een auto wil gebruiken?',antwoord:`Dat deel is geen eigenwoningschuld en valt in box 3. Maak het als apart leningdeel zichtbaar en reken de netto last zonder aftrek. Bespreek ook alternatieven en de lange looptijd voor een kortlevend goed. Leg de keuze van de klant vast.`,tags:['consumptief','auto','box 3'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-232',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant met een box 3-deel later gaat verbouwen?',antwoord:`Een nieuwe lening voor de verbouwing kan eigenwoningschuld zijn als aan de voorwaarden wordt voldaan. Het oude box 3-deel blijft box 3. Het kan dan verstandig zijn eerst het box 3-deel af te lossen. Bespreek de opties en leg de afweging vast.`,tags:['box 3','verbouwing','herstructurering'],bron:'Belastingdienst'},
 {id:'fex-233',thema:'fiscaal-eigen-woning',vraag:'Hoe controleer je of een klant de informatieplicht voor een familielening heeft nagekomen?',antwoord:`Vraag de aangifte van het betreffende jaar op of laat de klant bevestigen dat de gegevens zijn opgegeven. Controleer of naam en gegevens van de geldgever volledig zijn. Leg vast wat is gecontroleerd. Bij twijfel adviseer je de klant om een fiscalist te raadplegen.`,tags:['informatieplicht','controle','familielening'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-234',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als achteraf blijkt dat een leningdeel ten onrechte als eigenwoningschuld is behandeld?',antwoord:`De Belastingdienst kan de aftrek corrigeren via een navorderingsaanslag. Daarover kan belastingrente verschuldigd zijn. Bespreek de situatie met de klant en verwijs naar een fiscalist. Leg vast hoe de fout is ontstaan en welke stappen zijn gezet.`,tags:['navordering','correctie','fout'],bron:'Algemene wet inzake rijksbelastingen'},
 {id:'fex-235',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met de netto last als de klant een laag inkomen heeft?',antwoord:`Bij een laag inkomen kan het fiscale voordeel kleiner zijn dan verwacht, bijvoorbeeld door heffingskortingen. Reken met de werkelijke fiscale positie van de klant, niet met een standaardtarief. Laat bij twijfel een fiscale berekening maken en leg de uitgangspunten vast.`,tags:['laag inkomen','netto last','heffingskorting'],bron:'Belastingdienst'},
 {id:'fex-236',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met renteaftrek bij een klant met AOW?',antwoord:`Na de AOW-leeftijd kan het tarief in de eerste schijf anders zijn dan daarvoor. Het fiscale voordeel kan daardoor veranderen. Gebruik de actuele tarieven van de Belastingdienst voor de berekening. Laat het verloop van de netto last na pensionering zien.`,tags:['aow','pensioen','netto last'],bron:'Belastingdienst'},
 {id:'fex-237',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er fiscaal bij een seniorenverhuizing naar een kleinere woning?',antwoord:`Bij verkoop van de oude woning ontstaat vaak een eigenwoningreserve. Die beperkt de eigenwoningschuld voor de nieuwe woning. Kiest de klant toch voor een hypotheek, dan is het meerdere box 3-schuld. Laat de berekening zien en leg de afweging vast.`,tags:['senioren','verhuizing','eigenwoningreserve'],bron:'Wet IB 2001 art. 3.119aa'},
 {id:'fex-238',thema:'fiscaal-eigen-woning',vraag:'Hoe wordt meerwerk na oplevering van een nieuwbouwwoning gefinancierd?',antwoord:`Meerwerk dat na de levering wordt uitgevoerd, is een verbetering van de eigen woning. Een lening daarvoor kan eigenwoningschuld zijn als aan de aflossingseis wordt voldaan. Een eventuele eigenwoningreserve speelt ook hier mee. Bewaar de meerwerkopdracht en facturen.`,tags:['meerwerk','nieuwbouw','verbetering'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-239',thema:'fiscaal-eigen-woning',vraag:'Voldoet een opeethypotheek aan de aflossingseis?',antwoord:`Een opeethypotheek lost tijdens de looptijd niet af. Daardoor voldoet die in de regel niet aan de aflossingseis. Het deel dat na 2012 is ontstaan, is dan geen eigenwoningschuld. Laat de klant dit verschil zien en leg vast dat de fiscale gevolgen zijn besproken.`,tags:['opeethypotheek','aflossingseis','senioren'],bron:'Wet IB 2001'},
 {id:'fex-240',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning bij emigratie?',antwoord:`Na emigratie is de woning in de regel geen eigen woning meer, tenzij de klant er zijn hoofdverblijf houdt. De klant wordt dan buitenlands belastingplichtige. Er kunnen gevolgen zijn voor overgangsrecht en eigenwoningreserve. Verwijs naar een fiscalist met internationale kennis.`,tags:['emigratie','buitenland','hoofdverblijf'],bron:'Belastingdienst'},
 {id:'fex-241',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning als een klant terugkeert uit het buitenland?',antwoord:`Gaat de klant weer in de woning wonen, dan kan die opnieuw een eigen woning worden. Of de schuld weer eigenwoningschuld is, hangt af van de fiscale historie en de aflossingseis. Laat dit per situatie toetsen. Vraag de historie op bij de geldverstrekker.`,tags:['remigratie','terugkeer','fiscale historie'],bron:'Belastingdienst'},
 {id:'fex-242',thema:'fiscaal-eigen-woning',vraag:'Wat speelt er bij de eigenwoningregeling voor een ondernemer met wisselend inkomen?',antwoord:`De renteaftrek verlaagt het belastbare inkomen in box 1, maar het voordeel hangt af van het inkomen per jaar. Bij een verlies kan het voordeel lager zijn. Reken met een voorzichtig scenario. Leg vast welk inkomen is gebruikt.`,tags:['ondernemer','wisselend inkomen','netto last'],bron:'Belastingdienst'},
 {id:'fex-243',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met een klant die verwacht dat de renteaftrek verder wordt beperkt?',antwoord:`Leg uit dat de klant met de actuele regels rekent, maar dat toekomstige wijzigingen kunnen gebeuren. Laat een scenario zien met minder of geen aftrek. Zo wordt duidelijk of de woonlast ook dan betaalbaar blijft. Leg dit scenario en de reactie van de klant vast.`,tags:['scenario','beleidsrisico','betaalbaarheid'],bron:'Wft'},
 {id:'fex-244',thema:'fiscaal-eigen-woning',vraag:'Waarom is het belangrijk om de fiscale gevolgen bij oversluiten vooraf te berekenen?',antwoord:`Bij oversluiten kunnen overgangsrecht, looptijden en de fiscale status van extra bedragen veranderen. Een fout is achteraf vaak niet te herstellen. Maak een vergelijking van oude en nieuwe situatie per leningdeel. Leg de berekening vast in het dossier.`,tags:['oversluiten','berekening','dossier'],bron:'Wft'},
 {id:'fex-245',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er als een klant een eigenwoningschuld aflost en later opnieuw wil lenen?',antwoord:`Een nieuwe lening voor de eigen woning valt onder de huidige regels met aflossingseis. Een eerder afgelost bedrag met overgangsrecht komt niet terug. Voor consumptieve besteding is de nieuwe lening box 3-schuld. Bespreek dit voordat de klant extra aflost.`,tags:['heropname','aflossing','overgangsrecht'],bron:'Wet IB 2001 art. 3.119a'},
 {id:'fex-246',thema:'fiscaal-eigen-woning',vraag:'Wat is een kredietlimiet op de eigen woning fiscaal?',antwoord:`Een krediethypotheek of kredietlimiet kan alleen eigenwoningschuld zijn voor het deel dat aan de woning is besteed. Bovendien moet worden voldaan aan de aflossingseis. Een doorlopend krediet zonder vast aflossingsschema voldoet daar meestal niet aan. Controleer de productvoorwaarden.`,tags:['krediethypotheek','aflossingseis','box 3'],bron:'Wet IB 2001'},
 {id:'fex-247',thema:'fiscaal-eigen-woning',vraag:'Wat gebeurt er met de eigen woning bij een gedwongen verkoop?',antwoord:`Ook bij een gedwongen verkoop is er een vervreemding. Blijft er een restschuld over, dan valt die bij verkoop vanaf 2018 in box 3. Een eventuele overwaarde kan een eigenwoningreserve opleveren. Verwijs de klant tijdig naar schuldhulp en leg de gemaakte afspraken vast.`,tags:['gedwongen verkoop','restschuld','executie'],bron:'Belastingdienst'},
 {id:'fex-248',thema:'fiscaal-eigen-woning',vraag:'Hoe ga je om met tegenstrijdige informatie tussen klant en geldverstrekker over de fiscale status?',antwoord:`Ga uit van de stukken die het best te controleren zijn, zoals de oorspronkelijke akte en historische overzichten. Vraag bij de geldverstrekker een onderbouwing op. Neem geen fiscale status aan zonder bewijs. Leg de verschillen en de gekozen benadering vast.`,tags:['tegenstrijdig','bewijs','dossier'],bron:'Wft'},
 {id:'fex-249',thema:'fiscaal-eigen-woning',vraag:'Moet een adviseur controleren of de klant fiscaal partner is?',antwoord:`Ja. Het fiscaal partnerschap bepaalt hoe de eigenwoningpost kan worden verdeeld en hoe eigendom en schuld fiscaal uitwerken. Vraag naar huwelijk, samenlevingscontract, kinderen en gezamenlijke eigendom. Leg de uitkomst vast in het dossier.`,tags:['fiscaal partner','controle','dossier'],bron:'Wet IB 2001 art. 2.17'},
 {id:'fex-250',thema:'fiscaal-eigen-woning',vraag:'Hoe werkt het als een deel van de woning als zelfstandige wooneenheid wordt verhuurd?',antwoord:`Een zelfstandige wooneenheid die aan een ander wordt verhuurd, is voor dat deel geen eigen woning. Dat deel valt met het bijbehorende deel van de schuld in box 3. De kamerverhuurvrijstelling is bedoeld voor kamers in de eigen woning, niet voor zelfstandige woonruimte. Leg de splitsing van waarde en schuld vast.`,tags:['wooneenheid','verhuur','splitsing'],bron:'Belastingdienst'},
]);
